// Üretilen dosya: tool/ozgun/uret.py. Kimya ve Malzeme · Su ve çevre kimyası, sert su, asit yağmurları, atmosfer kirleticileri, geri dönüşüm ve yeşil kimya ilkeleri (orta).
const ozChemistry18Orta = <(String, String, List<String>, String)>[
  ('Geçici sertliğe sahip bir su örneği ısıtıldığında kalsiyum bikarbonatın parçalanma tepkimesinde CaCO₃ katısının yanı sıra hangi maddeler açığa çıkar?', 'CO₂ gazı ve H₂O sıvısı', ['H₂ gazı ve Ca(OH)₂ katısı', 'O₂ gazı ve H₂CO₃ çözeltisi', 'CO gazı ve CaO katısı'], 'Ca(HCO₃)₂ sulu çözeltisi ısıtıldığında CaCO₃(k) + CO₂(g) + H₂O(s) ürünlerine ayrışarak sudaki Ca²⁺ derişimini azaltır.'),
  ('Sentetik deterjanların sert sularda bile köpürme ve temizleme gücünü kaybetmemesinin temel kimyasal nedeni nedir?', 'Kalsiyum ve magnezyum tuzlarının suda çözünür kalması', ['Sert sudaki katyonları kaynatmadan gaz haline geçirmesi', 'Suyun pH değerini kuvvetli asidik bölgeye çekmesi', 'Yapılarında hiç hidrofobik hidrokarbon zinciri bulunmaması'], 'Deterjanların sülfonat veya sülfat uçları Ca²⁺ ve Mg²⁺ iyonlarıyla suda çözünmeyen çökelti oluşturmadığından sert suda kesilme yaşanmaz.'),
  ('Yağmur suyunun toprağa süzülürken kireç taşı (CaCO₃) kayaçlarını çözüp geçici sertlik kazanmasında havadan aldığı hangi gaz doğrudan rol oynar?', 'Karbondioksit (CO₂)', ['Azot monoksit (NO)', 'Oksijen (O₂)', 'Metan (CH₄)'], 'Yağmur suyunda çözünen CO₂ zayıf karbonik asit oluşturur; bu asidik su CaCO₃ kayaçlarını çözünür Ca(HCO₃)₂ formuna dönüştürerek suya geçici sertlik kazandırır.'),
  ('Litresinde 200 mg çözünmüş CaCO₃ eşdeğeri sertlik barındıran 5 litrelik bir su örneği tam olarak kaç gram CaCO₃ eşdeğeri sertlik içerir?', '1,0 gram', ['0,2 gram', '2,5 gram', '10,0 gram'], '1 litrede 200 mg CaCO₃ eşdeğeri bulunduğuna göre 5 litrede 5 × 200 mg = 1000 mg yani 1,0 gram CaCO₃ eşdeğeri sertlik vardır.'),
  ('Sert suyun evsel tesisatlarda ve sıcak su borularında oluşturduğu kireç tortusunun enerji tüketimine etkisi nasıldır?', 'Isı iletimini yavaşlatarak enerji kaybını artırır', ['Suyun kaynama noktasını düşürerek yakıt tasarrufu sağlar', 'Metal yüzeylerde elektrik iletkenliğini yükselterek ısınmayı hızlandırır', 'Borulardaki su basıncını düşürerek pompaların yükünü azaltır'], 'Kalsiyum karbonat tabakası ısı yalıtkanı gibi davranarak ısıtıcı rezistanslardan suya ısı geçişini zorlaştırır ve enerji tüketimini artırır.'),
  ('Kireç tutmuş bir ısıtıcıya sirke döküldüğünde gözlenen kabarcıkların kimyasal formülü aşağıdakilerden hangisidir?', 'CO₂', ['H₂', 'O₂', 'Cl₂'], 'Kalsiyum karbonat (CaCO₃) asitlerle tepkimeye girdiğinde karbonik asit üzerinden parçalanarak karbondioksit (CO₂) gazı kabarcıkları çıkarır.'),
  ('Sodyum stearat (C₁₇H₃₅COONa) yapısındaki beyaz kalıp sabun Ca²⁺ içeren sert suya eklendiğinde oluşan çökeltinin formülü nedir?', '(C₁₇H₃₅COO)₂Ca', ['C₁₇H₃₅COOCa', 'Ca₂(C₁₇H₃₅COO)', 'Na₂Ca(C₁₇H₃₅COO)₂'], 'Stearat anyonu (-1) yüklü, kalsiyum katyonu (+2) yüklü olduğundan yük denkliği gereği suda çözünmeyen (C₁₇H₃₅COO)₂Ca tuzu çöker.'),
  ('Kalıcı su sertliğini gidermek amacıyla suya çamaşır sodası eklendiğinde kullanılan bileşiğin kimyasal adı nedir?', 'Sodyum karbonat (Na₂CO₃)', ['Sodyum klorür (NaCl)', 'Kalsiyum sülfat (CaSO₄)', 'Magnezyum oksit (MgO)'], 'Çamaşır sodası yani sodyum karbonat (Na₂CO₃), sudaki Ca²⁺ iyonlarını CaCO₃ katısı halinde çöktürerek kalıcı sertliği gidermede kullanılır.'),
  ('Kalıcı sertliğe sahip CaSO₄ çözeltisine sodyum karbonat (Na₂CO₃) eklendiğinde suyun yumuşamasını sağlayan net iyon tepkimesi hangisidir?', 'Ca²⁺(suda) + CO₃²⁻(suda) → CaCO₃(k)', ['Na⁺(suda) + SO₄²⁻(suda) → Na₂SO₄(k)', 'Ca²⁺(suda) + 2Na⁺(suda) → Ca(k) + 2Na²⁺(suda)', 'SO₄²⁻(suda) + CO₃²⁻(suda) → SO₃(g) + CO₄⁴⁻(suda)'], 'Eklenen karbonat (CO₃²⁻) iyonları çözeltideki Ca²⁺ katyonlarıyla birleşerek çözünürlüğü çok düşük olan CaCO₃ katısını çöktürür ve suyu yumuşatır.'),
  ('Sodyum formundaki bir katyon değiştirici reçineden (R-Na) geçen sert sudaki 1 mol Mg²⁺ iyonu reçineye tutunduğunda suya kaç mol Na⁺ iyonu salınır?', '2 mol', ['1 mol', '3 mol', '0,5 mol'], 'Elektriksel yük denkliğinin korunması için reçineye bağlanan her bir (+2) yüklü Mg²⁺ iyonuna karşılık suya iki adet (+1) yüklü Na⁺ iyonu geçer.'),
  ('Uzun süre kullanıldığı için Ca²⁺ ve Mg²⁺ iyonlarıyla doygunluğa ulaşan bir su yumuşatma reçinesini yeniden aktif hale (rejenerasyon) getirmek için hangi çözeltiyle yıkamak gerekir?', 'Derişik sodyum klorür (tuzlu su) çözeltisi', ['Saf kireç taşı süspansiyonu', 'Seyreltik magnezyum sülfat çözeltisi', 'Sert kuyu suyu'], 'Tükenen reçinedeki Ca²⁺ ve Mg²⁺ iyonlarını söküp reçineyi tekrar Na⁺ formuna dönüştürmek için yüksek derişimli NaCl (tuzlu su) çözeltisi kullanılır.'),
  ('Laboratuvarlarda hem katyonları hem anyonları tamamen giderilmiş deiyonize (demineralize) su elde etmek için hangi reçine kombinasyonu kullanılır?', 'H⁺ formunda katyon değiştirici ve OH⁻ formunda anyon değiştirici reçine', ['Na⁺ formunda katyon değiştirici ve Cl⁻ formunda anyon değiştirici reçine', 'Ca²⁺ formunda katyon değiştirici ve CO₃²⁻ formunda anyon değiştirici reçine', 'K⁺ formunda katyon değiştirici ve SO₄²⁻ formunda anyon değiştirici reçine'], 'Katyon reçinesi metal iyonlarını tutup H⁺ verir, anyon reçinesi ise negatif iyonları tutup OH⁻ verir; birleşen H⁺ ve OH⁻ saf H₂O oluşturur.'),
  ('Litresinde 150 mg çözünmüş CaCO₃ eşdeğeri sertlik bulunan bir suyun sertliği kaç Fransız sertlik derecesidir (°f)?', '15', ['1,5', '150', '30'], '1 Fransız sertlik derecesi 10 mg/L CaCO₃ eşdeğeri olduğuna göre, 150 mg/L CaCO₃ içeren suyun sertliği 150 / 10 = 15 °f olur.'),
  ('Alman sertlik derecesi (°dH) birimi, sudaki sertlik katyonlarının hangi bileşik cinsinden eşdeğer kütlesini temel alır?', 'Kalsiyum oksit (CaO)', ['Sodyum hidroksit (NaOH)', 'Magnezyum klorür (MgCl₂)', 'Potasyum sülfat (K₂SO₄)'], '1 Alman sertlik derecesi, 1 litre suda 10 mg (100 mL\'de 1 mg) kalsiyum oksit (CaO) eşdeğerine karşılık gelen sertliği ifade eder.'),
  ('Termik santrallerin veya fabrikaların soğutma sularını herhangi bir kimyasal atık içermemesine rağmen doğrudan sıcak halde akarsulara bırakmasının balık ölümlerine yol açma nedeni nedir?', 'Yükselen su sıcaklığının çözünmüş oksijen miktarını düşürmesi ve balıkların metabolik oksijen ihtiyacını artırması', ['Sıcak suyun akarsudaki sodyum klorür tuzlarını aniden çöktürerek suyu tatlılaştırması', 'Isınan su moleküllerinin kovalent bağlarının koparak zehirli hidrojen gazı salması', 'Sıcaklığın artmasıyla sudaki kalsiyum iyonlarının radyoaktif izotoplara dönüşmesi'], 'Termal kirlilik suyun sıcaklığını artırarak çözünmüş oksijen kapasitesini düşürürken soğukkanlı canlıların solunum hızını ve oksijen talebini yükselterek boğulmalara yol açar.'),
  ('Sabit basınç altında 5 °C sıcaklıktaki temiz bir dağ deresi ile 28 °C sıcaklıktaki sığ bir gölet karşılaştırıldığında çözünmüş oksijen doygunluk derişimi açısından hangisi doğrudur?', '5 °C\'deki dağ deresinde oksijenin doygunluk derişimi daha yüksektir', ['28 °C\'deki gölette oksijenin doygunluk derişimi daha yüksektir', 'Her iki su kütlesinde sıcaklıktan bağımsız olarak doygunluk derişimi eşittir', '5 °C\'de oksijen gazı suda hiç çözünmeden tamamen buz kristaline hapsolur'], 'Düşük sıcaklık gazların sudaki çözünürlüğünü desteklediği için 5 °C\'deki suyun tutabileceği maksimum çözünmüş oksijen miktarı 28 °C\'dekinden belirgin biçimde fazladır.'),
  ('Henry Yasası\'na göre sabit sıcaklıkta deniz seviyesindeki bir göl ile yüksek rakımlı bir dağ gölü karşılaştırıldığında oksijenin sudaki çözünürlüğü yüksek rakımda nasıl etkilenir?', 'Atmosferdeki oksijen kısmi basıncı düştüğü için çözünürlük azalır', ['Atmosfer basıncı düştüğü için gaz molekülleri suya daha çok girer', 'Yüksek rakımda oksijenin mol kütlesi büyüdüğü için çözünürlük artar', 'Basınç değişimi gazların sıvıdaki çözünürlüğünü hiçbir şekilde etkilemez'], 'Henry Yasası (C = k·P) uyarınca sabit sıcaklıkta bir gazın sıvıdaki çözünürlüğü o gazın kısmi basıncıyla doğru orantılıdır; irtifa arttıkça kısmi basınç ve çözünürlük düşer.'),
  ('Klorlama ile dezenfekte edilen bir içme suyunda pH değerinin 8,5\'in üzerine çıkması dezenfeksiyon verimini nasıl etkiler?', 'HOCl molekülleri OCl⁻ iyonuna dönüştüğü için dezenfeksiyon etkinliği azalır', ['Cl⁻ iyonları tamamen Cl₂ gazına dönüşerek verimi on katına çıkarır', 'Suyun sertliği aniden sıfırlanarak bakterilerin çoğalmasını hızlandırır', 'Hipokloröz asit parçalanarak suyu kuvvetli asidik hale getirir'], 'Yüksek pH\'ta HOCl ⇌ H⁺ + OCl⁻ dengesi sağa kayar; negatif yüklü hipoklorit (OCl⁻) iyonu bakteri hücre duvarından HOCl kadar kolay geçemediğinden etkinlik düşer.'),
  ('İçme suyu arıtımında ozonlama (O₃) yönteminin klorlamaya (Cl₂) kıyasla şebeke boru hattı boyunca taşıdığı en önemli dezavantaj nedir?', 'Ozonun kararsız olup hızla bozunması nedeniyle boru hattında kalıcı koruma sağlamaması', ['Ozon gazının suda çözünmeyen kireç taşı tortusu oluşturarak boruları tıkaması', 'Ozonun sudaki bakteri ve virüslere karşı yükseltgeme gücünün çok düşük olması', 'Ozonlama işleminin suya keskin ve kalıcı çamaşır suyu kokusu bırakması'], 'Ozon çok güçlü bir yükseltgendir ancak yarı ömrü kısadır; kısa sürede O₂\'ye dönüştüğünden şebeke hattındaki ikincil kirlenmelere karşı "bakiye dezenfektan" bırakmaz.'),
  ('Ozonlama ile dezenfekte edilen içme suyunda tepkimeye girmeden kalan fazla ozon (O₃) molekülleri bozunduğunda suya hangi zararsız maddeyi bırakır?', 'Çözünmüş oksijen (O₂)', ['Hidrojen klorür (HCl)', 'Karbon monoksit (CO)', 'Kükürt dioksit (SO₂)'], 'Üç atomlu oksijen olan ozon (O₃) kararsızdır ve bozunduğunda moleküler oksijene (O₂) dönüşerek suda çözünmüş oksijen miktarını artırır ve kalıntı bırakmaz.'),
  ('Su arıtma tesislerinde klorlamanın koagülasyon, flokülasyon ve kum filtrasyonu aşamalarından SONRA uygulanmasının başlıca nedeni nedir?', 'Askıdaki katıların ve organik maddelerin kloru tüketmesini ve zararlı yan ürün oluşumunu önlemek', ['Klor gazının kum filtrelerindeki silisyum dioksit taneciklerini çözmesini engellemek', 'Suyun sertliğini artırmak için önce kireç taşı eklenmesini beklemek', 'Filtrasyon işleminin sudaki tüm çözünmüş oksijeni yok etmesini sağlamak'], 'Önce bulanıklık ve organik yük giderilirse hem gerekli klor dozu düşer hem de bakterilerin partiküller arkasına saklanması ve THM oluşumu engellenir.'),
  ('Şehir şebekesinin en uç noktalarındaki musluklardan akan suda bile 0,2 - 0,5 mg/L düzeyinde "serbest bakiye klor" bulunmasının istenme amacı nedir?', 'Dağıtım borularında sonradan oluşabilecek mikrobiyal sızıntılara karşı suyu korumak', ['Suyun sertlik derecesini düşürerek çamaşır makinelerini kireçten korumak', 'Musluk suyunun donma noktasını sıfırın altına çekerek kışın boruları korumak', 'Sudaki kalsiyum ve magnezyum iyonlarını kompleksleştirip tadı yumuşatmak'], 'Arıtma tesisinden çıkan su kilometrelerce boru hattından geçer; bakiye klor bu yolculuk sırasında oluşabilecek çatlak ve biyofilm kaynaklı kirlenmelere karşı güvence sağlar.'),
  ('Sodyum lauril sülfat veya sodyum dodesil benzen sülfonat gibi yaygın deterjanların sert suda çökelti oluşturmamasını sağlayan fonksiyonel baş grupları hangileridir?', 'Sülfat (-OSO₃⁻) veya sülfonat (-SO₃⁻) grupları', ['Karboksilat (-COO⁻) veya karbonat (-CO₃²⁻) grupları', 'Hidroksil (-OH) veya aldehit (-CHO) grupları', 'Eter (-O-) veya ester (-COOR) grupları'], 'Sabunlardaki karboksilat (-COO⁻) grubu Ca²⁺ ile çökerken, deterjanlardaki sülfonat (-SO₃⁻) ve sülfat (-OSO₃⁻) gruplarının Ca²⁺/Mg²⁺ tuzları suda çözünür.'),
  ('Fosfatlı katkı maddelerinin çevresel zararları nedeniyle günümüz toz deterjanlarında sertlik katyonlarını (Ca²⁺, Mg²⁺) tutmak için kullanılan gözenekli alüminosilikat minerallerine ne ad verilir?', 'Zeolitler', ['Asbestler', 'Kuvarsitler', 'Boksitler'], 'Sodyum alüminosilikat yapısındaki zeolitler, iyon değiştirici özellik göstererek yıkama suyundaki Ca²⁺ iyonlarını gözeneklerine hapseder ve çevreye fosfat yükü vermez.'),
  ('Denizli Pamukkale travertenlerinin bembeyaz katmanlar halinde çökelmesini sağlayan tersinir denge tepkimesi aşağıdakilerden hangisidir?', 'Ca(HCO₃)₂(suda) ⇌ CaCO₃(k) + CO₂(g) + H₂O(s)', ['CaCl₂(suda) + H₂SO₄(suda) ⇌ CaSO₄(k) + 2HCl(g)', 'Na₂CO₃(suda) + MgCl₂(suda) ⇌ MgCO₃(g) + 2NaCl(k)', 'CaO(k) + H₂O(s) ⇌ Ca(OH)₂(g)'], 'Yer altından yüksek basınçla çıkan termal su yüzeye ulaştığında basınç düşer, CO₂ gazı havaya kaçar ve denge sağa kayarak beyaz CaCO₃ travertenlerini çöktürür.'),
  ('İçinde hem Ca(HCO₃)₂ hem de CaCl₂ bulunan bir su örneği uzun süre kaynatılıp soğutularak süzüldüğünde süzüntü için hangisi kesinlikle doğrudur?', 'Geçici sertliği giderilmiş ancak CaCl₂ kaynaklı kalıcı sertliği devam etmektedir', ['Hem geçici hem kalıcı sertliği tamamen sıfırlanarak saf su elde edilmiştir', 'Süzüntüde hiç Ca²⁺ iyonu kalmamış, yalnızca HCO₃⁻ iyonları kalmıştır', 'Kaynatma sonucu CaCl₂ katısı çökmüş, Ca(HCO₃)₂ çözeltide kalmıştır'], 'Kaynatma işlemi yalnızca bikarbonat kaynaklı Ca(HCO₃)₂\'ı CaCO₃ olarak çöktürür; CaCl₂ ısıtmayla çökelmediğinden süzüntüde kalıcı sertlik sürer.'),
  ('Laboratuvarda bir su örneğinin toplam sertliğini (Ca²⁺ ve Mg²⁺ toplamını) kompleksometrik titrasyonla hassas biçimde ölçmek için hangi reaktif kullanılır?', 'EDTA', ['Fehling çözeltisi (Bakır(II) sülfat ve tartarat karışımı)', 'Gümüş nitrat (AgNO₃) standart çözeltisi', 'Potasyum permanganat (KMnO₄) çözeltisi'], 'EDTA, pH 10 tamponunda Eriokrom Siyahı T indikatörü eşliğinde Ca²⁺ ve Mg²⁺ iyonlarıyla 1:1 oranında kararlı kıskaç (şelat) kompleksleri oluşturarak sertlik tayininde kullanılır.'),
  ('UV dezenfeksiyon yönteminin ozonlama ile ortak olan ve büyük şehir şebekelerinde tek başına kullanılmasını kısıtlayan özelliği nedir?', 'Suda kalıcı (bakiye) dezenfektan etkisi bırakmaması', ['Suda yüksek derişimde kanserojen kloroform oluşturması', 'Suyun pH değerini aşırı yükselterek acı tat vermesi', 'Sert sulardaki kalsiyum iyonlarıyla birleşip bulanıklık yapması'], 'UV fiziksel bir işlemdir; lamba odasından çıkan suda hiçbir kimyasal kalıntı kalmadığından boru hattındaki olası sızıntılara karşı koruma sağlayamaz.'),
  ('Bulanıklığı (türbiditesi) çok yüksek olan çamurlu bir suya doğrudan UV dezenfeksiyonu uygulandığında verimin düşmesinin nedeni nedir?', 'Askıdaki katı taneciklerin UV ışınlarını soğurup saçarak mikroorganizmaları gölgelemesi', ['Çamurdaki kil minerallerinin UV ışığını görünür kırmızı ışığa çevirmesi', 'Bulanık sularda bakteri ve virüslerin hiç DNA taşımaması', 'UV ışınlarının sudaki oksijen gazını tamamen ozona dönüştürmesi'], 'UV dezenfeksiyonunun etkili olabilmesi için suyun berrak olması gerekir; askıdaki partiküller ışığın geçişini engeller ve mikroorganizmalara kalkan oluşturur.'),
  ('Saf suya oda sıcaklığında bir miktar klor gazı (Cl₂) çözüldüğünde çözeltinin pH değeri nasıl değişir?', 'H⁺ ve HOCl oluştuğu için pH değeri 7\'nin altına düşer', ['OH⁻ iyonları açığa çıktığı için pH değeri 7\'nin üzerine çıkar', 'Tepkimede asit veya baz oluşmadığından pH 7\'de sabit kalır', 'Önce 14\'e yükselip sonra tekrar 7\'ye döner'], 'Cl₂ + H₂O ⇌ HOCl + H⁺ + Cl⁻ dengesinde ortama kuvvetli asit kaynaklı H⁺ iyonları ve zayıf asit HOCl verildiği için çözelti asidik olur (pH < 7).'),
  ('Bir su örneğinin "toplam sertliği" aşağıdaki büyüklüklerden hangilerinin toplamına eşittir?', 'Geçici sertlik ile kalıcı sertliğin toplamına', ['Sodyum sertliği ile potasyum sertliğinin toplamına', 'Çözünmüş oksijen ile serbest klor derişimlerinin toplamına', 'Askıdaki katı madde ile çözünmüş CO₂ miktarının toplamına'], 'Suyun toplam sertliği, bikarbonatlardan kaynaklanan geçici (karbonat) sertliği ile sülfat/klorür/nitratlardan kaynaklanan kalıcı (karbonat olmayan) sertliğin toplamıdır.'),
  ('Yaz aylarında sığ göllerde balık ölümlerinin en sık güneş doğmadan hemen önceki şafak saatlerinde görülmesinin nedeni nedir?', 'Gece boyunca fotosentez dururken hem bitkilerin hem hayvanların solunumla çözünmüş oksijeni tüketmesi', ['Şafak vakti su sıcaklığının günün en yüksek değerine ulaşarak oksijeni uçurması', 'Geceleri atmosfer basıncının sıfıra düşerek sudaki tüm gazları vakumlaması', 'Sabah saatlerinde sudaki kireç taşının aniden sülfürik aside dönüşmesi'], 'Gündüz su bitkileri ve algler fotosentezle O₂ üretir; gece ışık olmadığından fotosentez durur, tüm canlıların solunumu devam ettiği için şafak vakti Ç.O. en alt düzeye iner.'),
  ('Aynı sıcaklık ve basınçta saf su ile yüksek tuzluluğa sahip deniz suyu karşılaştırıldığında oksijen gazının çözünürlüğü nasıldır?', 'Tuz iyonları su moleküllerini tuttuğu için deniz suyunda çözünmüş oksijen daha azdır', ['Deniz suyundaki sodyum klorür oksijenle bağ kurduğu için çözünürlük çok daha yüksektir', 'Tuzluluk oranı gazların sudaki çözünürlüğünü hiçbir biçimde değiştirmez', 'Saf suda oksijen hiç çözünmezken yalnızca tuzlu suda çözünür'], '"Salting-out" (tuzlama etkisi) nedeniyle tuz iyonları su moleküllerini hidratasyon kabuklarında tutar; gaz moleküllerini barındıracak serbest su azaldığından O₂ çözünürlüğü düşer.'),
  ('Londra tipi sis kimyasal açıdan "indirgen sis", Los Angeles tipi sis ise "yükseltgen sis" olarak sınıflandırılır. Bu ayrımın temel kimyasal dayanağı nedir?', 'Londra sisinin SO₂ gibi indirgen maddeler, Los Angeles sisinin O₃ ve PAN gibi kuvvetli yükseltgenler içermesi', ['Londra sisinin yalnızca metalleri yükseltgemesi, Los Angeles sisinin ise ametalleri indirgemesi', 'Londra sisinde pH değerinin bazik olması, Los Angeles sisinde pH değerinin çok düşük olması', 'Londra sisinin fotolizle oksijen üretmesi, Los Angeles sisinin ortamdan oksijen tüketmesi'], 'Londra sisindeki SO₂ yükseltgenmeye yatkın (indirgen) bir gazken, Los Angeles sisindeki ozon (O₃), NO₂ ve peroksiasetil nitrat (PAN) güçlü yükseltgenlerdir.'),
  ('Azot dioksit gazının su ile tepkimesi 2NO₂(g) + H₂O(s) → HNO₃(suda) + HNO₂(suda) şeklindedir. Bu tepkime redoks açısından neden bir öz yükseltgenme-indirgenme (disproporsiyonasyon) tepkimesidir?', 'NO₂\'deki +4 değerlikli azotun hem +5\'e yükseltgenip hem de +3\'e indirgenmesi nedeniyle', ['Suyun yapısındaki oksijenin hem serbest O₂ gazına hem de peroksite dönüşmesi nedeniyle', 'Tepkimeye giren iki gaz molekülünün tek bir asit molekülünde birleşmesi nedeniyle', 'Hidrojen atomlarının yükseltgenme basamağının +1\'den 0\'a ve +2\'ye değişmesi nedeniyle'], 'NO₂\'de azotun yükseltgenme basamağı +4\'tür; tepkime sonunda HNO₃ içinde +5\'e yükseltgenirken HNO₂ içinde +3\'e indirgenir.'),
  ('Yarı soy metallerden olan bakırdan (Cu) yapılmış tarihi kubbelerin temiz suda çözünmediği hâlde asit yağmurlarıyla zamanla aşınıp yeşilimsi tuzlara dönüşmesinin kimyasal açıklaması nedir?', 'Asit yağmurlarındaki nitrik ve sülfürik asit gibi oksijenli asitlerin yarı soy metalleri yükseltgeyebilmesi', ['Yağmur suyundaki çözünmüş hidrojen gazının bakır atomlarını indirgeyerek çözmesi', 'Bakırın pH 7\'nin altındaki her türlü zayıf organik asitle hidrojen gazı çıkararak tepkimesi', 'Karbonik asidin bakır yüzeyindeki elektronları kopararak saf bakır hidroksit oluşturması'], 'Bakır yarı soy bir metaldir; HCl gibi oksijensiz asitlerle tepkime vermez ancak asit yağmurlarındaki HNO₃ ve H₂SO₄ ile yükseltgenerek aşınır.'),
  ('Atmosferde gerçekleşen SO₂(g) + ½O₂(g) → SO₃(g) tepkimesi saf gaz fazında oldukça yavaştır. Kirli şehir havasında bu tepkimenin çok daha hızlı gerçekleşmesini sağlayan etken nedir?', 'Havadaki kurum, metal oksit partikülleri ve hidroksil (•OH) radikallerinin katalizör/başlatıcı rolü oynaması', ['Şehir havasındaki karbondioksit fazlalığının tepkime entalpisini pozitif yöne kaydırması', 'Azot gazının yüksek basınç altında kükürt dioksit moleküllerini sıkıştırıp parçalaması', 'Su buharının oksijen moleküllerini ozona dönüştürerek sıcaklığı 500 dereceye çıkarması'], 'Gaz fazında yavaş olan SO₂ yükseltgenmesi, havadaki ağır metal oksit içeren toz tanecikleri (heterojen kataliz) ve •OH radikalleri sayesinde hızlanır.'),
  ('Fotokimyasal sis oluşumunda sabah trafiğiyle önce NO derişimi artar, ardından NO₂ yükselir ve öğleye doğru O₃ ile PAN (peroksiasetil nitrat) zirve yapar. Uçucu organik bileşiklerin (VOC) bu döngüdeki kritik rolü nedir?', 'Ozon tüketmeden NO gazını NO₂ gazına yükseltgeyen peroksi radikalleri üreterek ozon birikimine yol açması', ['Güneşten gelen kızılötesi ışınları soğurup doğrudan sıvı nitrik asit damlacıklarına dönüşmesi', 'Atmosferdeki serbest oksijen atomlarını yakalayarak su buharı ve karbondioksit oluşturması', 'Azot dioksit gazını kararlı azot gazına indirgeyerek fotokimyasal dengeyi durdurması'], 'Normalde NO + O₃ → NO₂ + O₂ tepkimesi ozonu harcar; ancak VOC kaynaklı peroksi radikalleri (RO₂•) NO\'yu ozon harcamadan NO₂\'ye çevirir ve net O₃ birikir.'),
  ('Toprak pH\'ı 4,5\'in altına düştüğünde kil minerallerinin yapısındaki alüminyum hidroksit Al(OH)₃(k) + 3H⁺(suda) → Al³⁺(suda) + 3H₂O(s) tepkimesiyle çözünür. Bu durum göl ekosistemlerini nasıl etkiler?', 'Sulara taşınan Al³⁺ iyonları balıkların solungaçlarında mukus birikimine ve solunum yetmezliğine yol açar', ['Çözünen alüminyum iyonları göl suyunun pH değerini aniden 9,0\'un üzerine çıkararak bazikleştirir', 'Alüminyum katyonları sudaki tüm nitrat ve fosfatı çoğaltarak aşırı alg patlamasını hızlandırır', 'Balıkların kemik dokusundaki kalsiyumun yerine geçerek balıklarda aşırı büyümeye neden olur'], 'Topraktan yıkanıp göllere ulaşan çözünmüş Al³⁺ iyonları balıklar için son derece toksiktir; solungaçlarda çökelip iyon alışverişini ve solunumu engeller.'),
  ('pH değeri 4,3 olan bir asit yağmuru örneğindeki hidrojen iyonu [H⁺] derişimi, pH değeri 5,3 olan hafif asidik bir yağmur örneğindekinin kaç katıdır?', '10 katı', ['2 katı', '100 katı', '0,1 katı'], 'pH ölçeği on tabanında logaritmiktir (pH = -log[H⁺]). pH değerinin 5,3\'ten 4,3\'e 1 birim düşmesi, [H⁺] iyonu derişiminin 10¹ = 10 katına çıktığını gösterir.'),
  ('Kütlece %3,2 kükürt içeren 1 ton (1000 kg) linyit kömürünün tam yanması sonucunda oluşan kükürt dioksit (SO₂) gazı kaç kilogramdır? (S: 32, O: 16 g/mol)', '64 kg', ['32 kg', '48 kg', '96 kg'], '1000 kg kömürdeki kükürt kütlesi 1000 × 0,032 = 32 kg\'dır (1000 mol S). S + O₂ → SO₂ denklemine göre 1000 mol SO₂ oluşur; mol kütlesi 64 g/mol olduğundan 64 kg SO₂ açığa çıkar.'),
  ('Atmosfere salınan 2 mol kükürt trioksit (SO₃) gazının tamamı yağmur suyuyla sülfürik aside dönüştüğünde, bu asidi tamamen nötrleştirmek için kaç gram saf kalsiyum karbonat (CaCO₃) gerekir? (CaCO₃: 100 g/mol)', '200 gram', ['100 gram', '50 gram', '400 gram'], '2 mol SO₃ suyla 2 mol H₂SO₄ üretir. H₂SO₄ + CaCO₃ → CaSO₄ + CO₂ + H₂O denklemine göre 1\'e 1 oranında tepkime gerçekleştiğinden 2 mol yani 200 g CaCO₃ gerekir.'),
  ('3NO₂(g) + H₂O(s) → 2HNO₃(suda) + NO(g) tepkimesine göre 6 mol azot dioksit gazının sıcak yağmur damlacıklarıyla tam verimli tepkimesinden kaç mol nitrik asit oluşur?', '4 mol', ['6 mol', '3 mol', '2 mol'], 'Tepkime stokiyometrisine göre 3 mol NO₂ gazından 2 mol HNO₃ oluşmaktadır; dolayısıyla 6 mol NO₂ harcandığında (6 / 3) × 2 = 4 mol HNO₃ elde edilir.'),
  ('Bir mermer heykel yüzeyinden asit yağmurları etkisiyle CaCO₃(k) + H₂SO₄(suda) → CaSO₄(k) + CO₂(g) + H₂O(s) tepkimesine göre normal koşullarda 11,2 litre CO₂ gazı çıkışı gözlenmiştir. Aşınan CaCO₃ kaç gramdır? (CaCO₃: 100 g/mol)', '50 gram', ['100 gram', '25 gram', '75 gram'], 'Normal koşullarda 11,2 litre CO₂ gazı 11,2 / 22,4 = 0,5 moldür. Denkleme göre 1 mol CO₂ çıkışına karşılık 1 mol CaCO₃ aşındığından 0,5 × 100 = 50 gram mermer aşınmıştır.'),
  ('Baca gazı arıtma ünitesinde CaO(k) + SO₂(g) → CaSO₃(k) tepkimesi %80 verimle gerçekleşmektedir. Bacadan geçen 10 mol SO₂ gazının tutulması sonucunda kaç mol kalsiyum sülfit (CaSO₃) katısı elde edilir?', '8 mol', ['10 mol', '6 mol', '12,5 mol'], '%100 verimde 10 mol SO₂ gazından 10 mol CaSO₃ oluşurdu; tepkime %80 verimle çalıştığına göre 10 × 0,80 = 8 mol CaSO₃ katısı tutulur.'),
  ('1000 litrelik küçük bir süs havuzuna yağan asit yağmuru havuz suyunun pH değerini 7,0\'den 4,0\'e düşürmüştür (hacim değişimi ihmal edilirse). Havuzu tekrar nötr yapmak için en az kaç mol sodyum hidroksit (NaOH) eklenmelidir?', '0,1 mol', ['0,001 mol', '1,0 mol', '0,01 mol'], 'pH = 4,0 olduğunda [H⁺] = 10⁻⁴ M olur. 1000 litre suda n(H⁺) = 10⁻⁴ mol/L × 1000 L = 0,1 mol H⁺ vardır; bunu nötrleştirmek için 0,1 mol OH⁻ (0,1 mol NaOH) gerekir.'),
  ('Kuru kireç taşı tozu enjekte edilen bir termik santral bacasında 2CaCO₃(k) + 2SO₂(g) + O₂(g) → 2CaSO₄(k) + 2CO₂(g) tepkimesi gerçekleşiyor. 128 gram SO₂ gazını tamamen tutmak için en az kaç mol O₂ gazı harcanır? (SO₂: 64 g/mol)', '1 mol', ['2 mol', '0,5 mol', '4 mol'], '128 gram SO₂ = 128 / 64 = 2 moldür. Tepkime denkleminde 2 mol SO₂ için 1 mol O₂ harcandığı görülmektedir; bu nedenle en az 1 mol O₂ gerekir.'),
  ('Fotokimyasal sis döngüsünde NO₂(g) + hv → NO(g) + O(g) ve O(g) + O₂(g) → O₃(g) basamakları tam verimle gerçekleştiğinde, 0,4 mol NO₂ gazının fotolizinden en fazla kaç gram ozon (O₃) oluşabilir? (O: 16 g/mol)', '19,2 gram', ['12,8 gram', '9,6 gram', '28,8 gram'], '1 mol NO₂ fotoliz olduğunda 1 mol O radikali, ondan da 1 mol O₃ oluşur. 0,4 mol NO₂\'den 0,4 mol O₃ elde edilir. O₃\'ün mol kütlesi 3 × 16 = 48 g/mol olduğundan 0,4 × 48 = 19,2 gramdır.'),
  ('pH değeri 4,0 olan 500 mL asit yağmuru suyu ile pH değeri 5,0 olan 500 mL asit yağmuru suyu karıştırıldığında oluşan 1 litrelik yeni karışımın [H⁺] derişimi kaç mol/L olur?', '5,5 × 10⁻⁵ M', ['1,0 × 10⁻⁴ M', '5,0 × 10⁻⁵ M', '4,5 × 10⁻⁵ M'], 'Birinci çözeltiden 0,5 L × 10⁻⁴ M = 5 × 10⁻⁵ mol H⁺, ikinciden 0,5 L × 10⁻⁵ M = 0,5 × 10⁻⁵ mol H⁺ gelir. Toplam 5,5 × 10⁻⁵ mol H⁺ / 1 L = 5,5 × 10⁻⁵ M bulunur.'),
  ('Aşağıda iki farklı şehrin sabah saatlerindeki atmosferik ölçüm verileri verilmiştir: A şehrinde sıcaklık 2 °C, bağıl nem %92, yüksek SO₂ ve kurum; B şehrinde sıcaklık 28 °C, bağıl nem %35, yüksek NOₓ ve hidrokarbon. Buna göre hangi çıkarım doğrudur?', 'A şehrinde Londra tipi indirgen sis, B şehrinde Los Angeles tipi yükseltgen sis görülür', ['A şehrinde fotokimyasal ozon birikimi, B şehrinde sülfüröz asit sisi baskındır', 'Her iki şehirde de sis oluşumu için güneşin morötesi ışınları zorunludur', 'B şehrindeki sisin temel kaynağı ısınma amaçlı yüksek kükürtlü kömür yakımıdır'], 'Düşük sıcaklık, yüksek nem, SO₂ ve kurum Londra tipi (indirgen) sisi; yüksek sıcaklık, düşük nem, güneş ışığı, NOₓ ve hidrokarbonlar ise Los Angeles tipi (yükseltgen) sisi tanımlar.'),
  ('Aşağıdaki gaz çiftlerinden hangisinin atmosferdeki derişimlerinin birlikte artması hem asit yağmuru oluşumunu hem de fotokimyasal sis oluşumunu ortak olarak tetikler?', 'Azot monoksit (NO) ve azot dioksit (NO₂)', ['Kükürt dioksit (SO₂) ve kükürt trioksit (SO₃)', 'Karbondioksit (CO₂) ve metan (CH₄)', 'Amonyak (NH₃) ve hidrojen sülfür (H₂S)'], 'NOₓ gazları (NO ve NO₂) su buharı ve •OH radikalleriyle HNO₃ oluşturarak asit yağmurlarına katılırken, güneş ışığı ve VOC varlığında fotokimyasal sis döngüsünü başlatır.'),
  ('Ağır sanayi tesislerinin bacalarının çok yüksek inşa edilmesi yerel hava kirliliğini azaltmak amacıyla uygulanmış ancak beklenmedik bir bölgesel çevre sorununa yol açmıştır. Bu durumun temel sonucu nedir?', 'Kirletici gazların üst rüzgârlarla yüzlerce kilometre taşınarak komşu bölgelerde asit yağmurlarına sebep olması', ['Baca yüksekliği arttıkça kükürt dioksit gazının bacadan çıkmadan tamamen katı kükürde dönüşmesi', 'Gazların doğrudan stratosfere ulaşıp yararlı ozon tabakasının kalınlığını iki katına çıkarması', 'Yüksek bacalardan çıkan karbondioksitin yer çekimi etkisiyle fabrika bahçesine sıvı olarak çökmesi'], 'Yüksek bacalar yerel duman yoğunluğunu düşürse de SO₂ ve NOₓ gazlarının atmosferde kalış süresini ve taşınım mesafesini uzatarak sınır ötesi asit yağmurlarına yol açar.'),
  ('Bir göl suyunun alkalinitesi (asit nötrleştirme kapasitesi) bikarbonat [HCO₃⁻] derişimiyle ölçülür. Üst üste birkaç yıl asit yağmuruna maruz kalan bir gölde ilk yıllarda pH çok az değişirken son yılda pH\'ın hızla 6,5\'ten 4,2\'ye düşmesi nasıl açıklanır?', 'Göldeki bikarbonat tampon kapasitesinin tamamen tükenmesiyle eklenen asidin doğrudan serbest H⁺ derişimini artırması', ['Son yılda göldeki su sıcaklığının düşmesiyle suyun iyonlaşma sabitinin bin kat büyümesi', 'Asit yağmurlarının ilk yıllarda bazik, yalnızca son yılda kuvvetli asidik karakter taşıması', 'Göl tabanındaki silikat kayalarının son yılda aniden çözünerek sülfürik asit üretmeye başlaması'], 'HCO₃⁻ + H⁺ → H₂CO₃ tampon sistemi tükenene kadar pH değişimine direnir; tampon tükendiğinde (eşdeğerlik noktası aşıldığında) pH keskin biçimde düşer.'),
  ('Atmosferde amonyak (NH₃) gazı salımının yoğun olduğu tarımsal bölgelerde yağmur suyunun sülfat (SO₄²⁻) ve nitrat (NO₃⁻) iyonları bakımından zengin olmasına rağmen pH değerinin 6,0 civarında ölçülmesinin nedeni nedir?', 'Bazik amonyak gazının atmosferdeki asitleri nötrleştirerek amonyum sülfat ve amonyum nitrat tuzlarına dönüştürmesi', ['Amonyak gazının sülfürik asidi parçalayarak tekrar kükürt ve oksijen elementlerine ayırması', 'Tarımsal bölgelerde yağmur damlalarının sülfat ve nitrat iyonlarını hiç çözmeden yere inmesi', 'Amonyağın güneş ışığıyla birleşip yağmur suyundaki hidrojen iyonlarını hidrojen gazı olarak uçurması'], 'NH₃ bazik bir gazdır; atmosferdeki H₂SO₄ ve HNO₃ ile tepkimeye girerek (NH₄)₂SO₄ ve NH₄NO₃ aerosollerini oluşturur, böylece yağmurun serbest asitliğini maskeler.'),
  ('Aynı asit yağmuruna maruz kalan açık alandaki bir mermer heykel (CaCO₃), bir granit anıt (kuvars ve feldispat ağırlıklı) ve çinkodan (Zn) yapılmış bir çatı kaplaması karşılaştırıldığında kimyasal aşınma direnci en yüksek olan hangisidir?', 'Granit anıt, çünkü silikat yapılı kuvars mineralleri sülfürik ve nitrik asitle tepkimeye girmez', ['Mermer heykel, çünkü kalsiyum karbonat asitlerle karşılaştığında çözünmez elmas benzeri yapı kazanır', 'Çinko çatı kaplaması, çünkü amfoter metaller asidik ortamlarda tamamen pasifleşerek hiç çözünmez', 'Mermer ve çinko eşit derecede dirençlidir, yalnızca granit anıt karbonik asitle hızla erir'], 'Mermer (CaCO₃) ve aktif metal çinko (Zn) asitlerle hızla tepkimeye girer; ancak granitin ana bileşeni olan kuvars (SiO₂) ve silikatlar HF dışındaki asitlere karşı çok dirençlidir.'),
  ('Kuru çökelme (dry deposition) ve yaş çökelme (wet deposition) kavramları karşılaştırıldığında, kurak iklime sahip sanayi bölgelerinde tarihi yapıların yine de asidik korozyona uğramasının sebebi nedir?', 'SO₂, NO₂ gazları ile asidik sülfat/nitrat partiküllerinin yağış olmadan da yüzeylere tutunup yüzey nemiyle aside dönüşmesi', ['Kurak bölgelerde havadaki azot gazının doğrudan katı kristaller hâlinde mermer yüzeyleri çizmesi', 'Yağış olmadığında güneş ışınlarının kalsiyum karbonatı fotoliz yoluyla kalsiyum metaline indirgemesi', 'Kurak havalarda rüzgârla taşınan kum tanelerinin mermerle kimyasal nötrleşme tepkimesine girmesi'], 'Asidik kirleticiler yalnızca yağmurla (yaş çökelme) değil, gaz ve aerosol hâlinde doğrudan yüzeylere çökerek (kuru çökelme) çiy veya yüzey nemiyle asit oluşturup yapıları aşındırır.'),
  ('Bir laboratuvar deneyinde özdeş iki kapalı cam balondan birincisine SO₂ + nemli hava, ikincisine NO₂ + C₃H₆ (propilen) + kuru hava konulup her ikisi de UV lambasıyla aydınlatılıyor. İkinci balonda ozon ve göz yaşartıcı PAN oluşurken birincide oluşmamasının nedeni nedir?', 'Fotokimyasal sis ürünlerinin oluşumu için NO₂ fotolizi ve uçucu hidrokarbon radikallerinin gerekli olması', ['Kükürt dioksit gazının morötesi ışınları tamamen yansıtarak hiçbir kimyasal bağ kırılmasına izin vermemesi', 'Su buharının bulunduğu hiçbir ortamda radikalik tepkimelerin termodinamik olarak başlayamaması', 'Propilen gazının yapısında doğrudan ozon molekülleri bulundurması ve ısıyla bunları serbest bırakması'], 'Ozon ve peroksiasetil nitrat (PAN) oluşumu Los Angeles tipi fotokimyasal sis mekanizmasıdır; NO₂\'nin fotoliziyle O atomu üretimine ve hidrokarbonların (C₃H₆) radikal zincirine dayanır.'),
  ('Gündüz saatlerinde troposferde gerçekleşen NO₂ + •OH → HNO₃ tepkimesi hem asit yağmuru hem de fotokimyasal sis açısından değerlendirildiğinde nasıl bir ikili etkiye sahiptir?', 'Azot dioksiti radikal döngüsünden uzaklaştırıp fotokimyasal sisi sınırlarken nitrik asit üreterek asit yağmuruna katkı sağlar', ['Hem fotokimyasal ozon üretimini hızlandırır hem de atmosferdeki tüm sülfürik asidi nötrleştirir', 'Hidroksil radikallerini çoğaltarak metan gazının ömrünü uzatır ve yağmurun pH değerini yükseltir', 'Nitrik asidi parçalayarak gece saatlerinde güneş ışığı olmadan da ozon üretilmesini sağlar'], 'Bu sonlanma tepkimesi NO₂ ve •OH radikallerini bağlayarak fotokimyasal sis zincirini yavaşlatır, ancak oluşan HNO₃ yağışlarla yeryüzüne inerek asit yağmuru oluşturur.'),
  ('Kış sonunda dağlık bölgelerdeki karların ani erimesiyle akarsu ve göllerde "bahar asit şoku" (acid shock) denilen toplu balık ölümlerinin yaşanmasının temel mekanizması nedir?', 'Kış boyu kar tabakasında biriken asidik kirleticilerin ilk erime sularıyla yoğunlaşmış olarak tek seferde suya karışması', ['Kar kristallerinin erirken ortamdan ısı alarak suyun sıcaklığını düşürmesi ve suyun bazikleşmesi', 'Bahar aylarında ağaçların köklerinden göllere yüksek miktarda sülfürik asit salgılamaya başlaması', 'Eriyen kar suyunun hiç çözünmüş oksijen içermemesi nedeniyle pH değerinin 10\'un üzerine çıkması'], 'Kış boyunca yağan karda biriken H₂SO₄ ve HNO₃, baharda kar erimeye başladığında ilk eriyik fraksiyonunda yoğunlaşır ve göl pH\'ını birkaç gün içinde ani olarak düşürür.'),
  ('Topraktaki katyon değişim kapasitesi (KDK) dikkate alındığında, negatif yüklü kil ve humus yüzeylerine tutunmuş Ca²⁺, Mg²⁺ ve K⁺ iyonlarının asit yağmurlarıyla yıkanıp gitmesinin iyonik nedeni nedir?', 'Yağmurla gelen yüksek derişimli H⁺ iyonlarının kil yüzeylerindeki mineral katyonlarla yer değiştirerek onları çözeltiye geçirmesi', ['Sülfat ve nitrat anyonlarının kil yüzeylerini pozitif yükleyerek tüm katyonları elektriksel olarak itmesi', 'Hidrojen iyonlarının kalsiyum ve magnezyum katyonlarını metalik katılara indirgeyerek çökeltmesi', 'Asidik ortamda kil minerallerinin tamamen buharlaşarak tutunma yüzeyinin ortadan kalkması'], 'Kütle etkisi ve yüksek yük yoğunluğu nedeniyle bol miktardaki H⁺ iyonları negatif yüklü toprak kolloidlerine bağlanır ve bitki besini olan Ca²⁺, Mg²⁺, K⁺ iyonlarını yerinden sökerek yıkanmasına neden olur.'),
  ('Mermer bir yüzeyde oluşan alçı taşı kabuğunun (CaSO₄·2H₂O) yağmurdan doğrudan ıslanmayan saçak altı kısımlarda siyah renkli ve kalın kabuklar oluşturup sonradan parça parça kopmasının nedeni nedir?', 'Yağmurla yıkanmayan alçı taşının gözeneklerinde kurum ve kül biriktirmesi, kristalleşme hacmi farkıyla mermeri çatlatması', ['Saçak altındaki mermerin güneş görmediği için karbon elementine dönüşerek kömürleşmesi', 'Alçı taşının yalnızca karanlık ortamlarda demir sülfür bileşiğine dönüşerek siyah renk alması', 'Doğrudan yağmur alan yüzeylerde sülfürik asidin mermerle hiç tepkimeye girememesi'], 'Doğrudan yağmur alan yerlerde CaSO₄ çözünüp yıkanırken, korunaklı saçak altlarında SO₂ kuru çökelmeyle CaSO₄·2H₂O kabuğu yapar; bu kabuk is hapseder (siyahlaşır) ve daha büyük molar hacmiyle yüzeyi patlatır.'),
  ('Sıcaklık terselmesi (termal enversiyon) yaşanan durgun bir kış gününde bir vadi şehrinde Londra tipi sisin ölümcül boyutlara ulaşmasının fizikokimyasal açıklaması nedir?', 'Soğuk kirli hava tabakasının üstteki sıcak hava katmanı tarafından hapsedilerek dikey hava karışımının engellenmesi', ['Üstteki sıcak havanın alttaki kükürt dioksiti vakumlayarak stratosferden ozon indirmesi', 'Termal enversiyon sırasında atmosfer basıncının sıfıra yaklaşarak oksijenin uzaya kaçması', 'Sıcak hava katmanının yerdeki kömür sobalarının yanma verimini yüzde yüze çıkarması'], 'Normalde yükselen hava soğur ve dağılır; enversiyonda ise yerdeki soğuk hava kütlesinin üzerine sıcak hava tabakası kapak gibi oturur, dikey konveksiyon durur ve SO₂/partiküller vadide birikir.'),
  ('Dizel ve benzinli yakıtlarda "ultra düşük kükürtlü yakıt" standardına geçilmesi şehirlerdeki hangi kirletici türünü doğrudan azaltırken hangisi üzerinde tek başına belirleyici bir azalma sağlamaz?', 'SO₂ ve sülfat asitliğini doğrudan azaltır; ancak yüksek sıcaklık kaynaklı NOₓ oluşumunu tek başına engellemez', ['NOₓ salımını tamamen sıfırlar; ancak yakıttaki kükürt dioksit salımını iki katına çıkarır', 'Karbondioksit salımını yarıya indirir; ancak atmosferdeki hidrojen florür miktarını artırır', 'Fotokimyasal ozonu tamamen yok eder; ancak Londra tipi kükürtlü sisi şiddetlendirir'], 'SO₂ yakıtın içindeki kükürt safsızlığından kaynaklandığı için kükürtsüzleştirmeyle büyük ölçüde biter; ancak NOₓ yanma odasındaki havanın N₂ ve O₂ gazlarından oluştuğu için yakıtta kükürt olmasa da üretilir.'),
  ('Sağanak bir yağışın ilk on dakikasında toplanan yağmur suyu örneğinin pH değerinin, yağışın ikinci saatinde toplanan örneğin pH değerinden belirgin biçimde daha düşük olmasının nedeni nedir?', 'Atmosferde birikmiş asidik gaz ve aerosollerin yağışın başlangıcında yıkanarak havadan hızla uzaklaşması', ['Yağış uzadıkça bulutlardaki su damlacıklarının sıcaklığının artarak bazik özellik kazanması', 'İkinci saatte güneş ışınlarının yağmur suyundaki nitrik asidi tamamen amonyağa dönüştürmesi', 'Topraktan buharlaşan saf suyun ikinci saatteki yağmur damlalarına havada karışmaması'], 'Yağış başladığında havadaki çözünür kirleticiler (SO₂, NO₂, HNO₃, sülfat aerosolleri) ilk damlalarla süpürülür ("washout" etkisi); hava temizlendikçe sonraki yağmurun pH\'ı doğal 5,6 değerine yaklaşır.'),
  ('Bir laboratuvarda asit yağmuru simülasyonu için 0,002 mol H₂SO₄ ve 0,006 mol HNO₃ saf suda çözülerek toplam hacim 10 litreye tamamlanıyor. Hazırlanan bu yapay asit yağmurunun pH değeri kaçtır?', '3,0', ['2,0', '4,0', '2,5'], 'H₂SO₄\'ten 2 × 0,002 = 0,004 mol H⁺, HNO₃\'ten 0,006 mol H⁺ gelir; toplam n(H⁺) = 0,010 moldür. 10 L çözeltide [H⁺] = 0,010 / 10 = 10⁻³ M olur ve pH = -log(10⁻³) = 3,0 bulunur.'),
  ('Okyanus kıyısındaki temiz bölgelerde bile yağmur suyunda doğal kaynaklı az miktarda sülfat (SO₄²⁻) iyonuna rastlanmaktadır. Kömür veya volkan etkisi olmayan açık okyanus atmosferindeki bu doğal kükürt döngüsünün kaynağı nedir?', 'Denizel fitoplanktonların ürettiği dimetil sülfür (DMS) gazının atmosferde yükseltgenerek SO₂ ve sülfata dönüşmesi', ['Okyanus suyundaki sodyum klorür tuzunun güneş ısısıyla parçalanıp kükürt trioksit gazı çıkarması', 'Balıkların solunum sırasında karbondioksit yerine doğrudan sülfürik asit buharı üretmesi', 'Derin deniz akıntılarının atmosferdeki azot gazını kükürt izotoplarına dönüştürmesi'], 'Denizel fitoplanktonlar tarafından üretilen dimetil sülfür (CH₃)₂S atmosfere geçer ve hidroksil radikalleriyle yükseltgenerek doğal SO₂ ve sülfat aerosollerini oluşturur.'),
  ('Etilen (C2H4, MA: 28 g/mol) ile oksijenin (O2, MA: 32 g/mol) doğrudan katılma tepkimesinden yalnız etilen oksit (C2H4O, MA: 44 g/mol) sentezlendiğinde tepkimenin atom ekonomisi yüzde kaçtır?', '%100', ['%63,6', '%72,7', '%88,0'], '2 C2H4 + O2 -> 2 C2H4O tepkimesinde yan ürün oluşmadığı için giren tüm atomlar hedef ürüne katılır ve atom ekonomisi %100 olur.'),
  ('CH4 (16 g/mol) + 2 H2O (18 g/mol) -> CO2 (44 g/mol) + 4 H2 (2 g/mol) tepkimesi ile hidrojen gazı (H2) üretildiğinde bu sürecin atom ekonomisi yaklaşık yüzde kaçtır?', '%15,4', ['%33,3', '%52,0', '%84,6'], 'Hedef ürün kütlesi 4 x 2 = 8 g, girenlerin toplam kütlesi 16 + 36 = 52 g olduğundan atom ekonomisi (8 / 52) x 100 ≈ %15,4 bulunur.'),
  ('Bir kimyasal sentezde yüzde verimin (% verim) %98 çıkmasına rağmen atom ekonomisinin %25 çıkması aşağıdakilerden hangisini kanıtlar?', 'Tepkimede büyük kütleli istenmeyen yan ürünler oluştuğunu', ['Tepkimenin tam verimle gerçekleşemediğini ve reaktif arttığını', 'Katalizörün tepkime hızını düşürerek dengeyi sola kaydırdığını', 'Çözücü buharlaşması nedeniyle hedef ürünün bozunduğunu'], 'Yüzde verim hedef ürünün kuramsal sınıra yakınlığını ölçerken, düşük atom ekonomisi stokiyometrik olarak çok fazla yan ürün çıktığını gösterir.'),
  ('Karbondioksitin (CO2) süperkritik akışkan fazına geçebilmesi için aşılması gereken kritik sıcaklık ve kritik basınç değerleri yaklaşık olarak nedir?', '31,1 °C ve 73,8 atm', ['100,0 °C ve 1,0 atm', '0,0 °C ve 5,11 atm', '374,0 °C ve 218,0 atm'], 'CO2\'nin kritik noktası yaklaşık 31,1 °C ve 73,8 atm olup ılımlı koşullarda süperkritik faza ulaşabilmesi ısıya duyarlı maddeler için büyük avantaj sağlar.'),
  ('CaCO3(k) -> CaO(k) + CO2(g) tepkimesi ile sönmemiş kireç (CaO, MA: 56 g/mol) üretilirken (CaCO3 MA: 100 g/mol) sürecin atom ekonomisi yüzde kaçtır?', '%56', ['%44', '%78', '%100'], 'Hedef ürün CaO\'nun mol kütlesi 56 g/mol, giren CaCO3\'ün mol kütlesi 100 g/mol olduğundan atom ekonomisi (56 / 100) x 100 = %56 olur.'),
  ('2 mol C2H5OH (MA: 46 g/mol) kondenzasyonu ile 1 mol dietil eter (C4H10O, MA: 74 g/mol) ve 1 mol H2O (MA: 18 g/mol) elde ediliyorsa eter üretiminin atom ekonomisi yaklaşık yüzde kaçtır?', '%80,4', ['%61,7', '%92,0', '%46,0'], 'Girenlerin toplam kütlesi 2 x 46 = 92 g, hedef ürün dietil eter 74 g olduğundan atom ekonomisi (74 / 92) x 100 ≈ %80,4 hesaplanır.'),
  ('Sentez kimyasında "türevlendirmeden kaçınma" (8. yeşil kimya ilkesi) özellikle hangi işlemin sınırlandırılmasını hedefler?', 'Koruyucu grup ekleme ve çıkarma basamaklarının', ['Düşük basınç altında damıtma işlemlerinin', 'Heterojen katalizörlerin süzülerek geri kazanılmasının', 'Su içinde misel destekli emülsiyon tepkimelerinin'], 'Koruyucu grupların bağlanması ve çözülmesi ek reaktif tüketimine, basamak sayısının artmasına ve fazladan atık oluşmasına yol açar.'),
  ('Bir ilaç aktif maddesi üretiminde 25 kg hedef ürün elde edilirken arıtılamayan çözücü kayıpları ve yan ürünlerle birlikte toplam 600 kg atık çıkıyorsa bu sürecin E-faktörü kaçtır?', '24', ['0,04', '25', '575'], 'E-faktörü = Toplam atık kütlesi / Hedef ürün kütlesi = 600 kg / 25 kg = 24 olarak bulunur.'),
  ('Yeşil kimyanın 4. ilkesi olan "Daha güvenli kimyasalların tasarımı" neyi amaçlar?', 'Kimyasal ürünün işlevselliğini korurken zehirliliğini en aza indirmeyi', ['Tüm endüstriyel kimyasalların yalnızca saf sudan üretilmesini', 'Tepkime hızını artırmak için daha reaktif zehirli ara ürünler seçmeyi', 'Ürünlerin raf ömrünü uzatmak için yapısına ağır metal eklemeyi'], 'Bu ilke, maddenin istenen teknik/ticari performansını sürdürürken insan sağlığı ve çevre üzerindeki toksisitesini moleküler tasarımla azaltmayı hedefler.'),
  ('Süperkritik akışkanların özütleme ve kromatografi işlemlerinde üstün performans göstermesini sağlayan fiziksel özellik ikilisi hangisidir?', 'Sıvılara yakın çözme gücü (yoğunluk) ve gazlara yakın difüzyon hızı', ['Katılara yakın sertlik ve sıvılara yakın yüzey gerilimi', 'Gazlara yakın düşük yoğunluk ve sıvılara yakın yüksek viskozite', 'Plazmaya yakın elektriksel iletkenlik ve yüksek kırma indisi'], 'Süperkritik akışkanlar yüksek yoğunluklarıyla organik maddeleri iyi çözerken, düşük viskozite ve yüksek difüzyon katsayılarıyla gözeneklere hızla nüfuz eder.'),
  ('Sentez gazından (CO + 2 H2 -> CH3OH) metanol üretiminde (CO: 28, H2: 2, CH3OH: 32 g/mol) başlangıçta 56 g CO ve 8 g H2 tepkimeye sokulup 48 g CH3OH elde edilirse atom ekonomisi ve % verim sırasıyla kaçtır?', '%100 ve %75', ['%75 ve %100', '%87,5 ve %75', '%100 ve %80'], 'Tek ürün CH3OH oluştuğundan atom ekonomisi %100\'dür. 2 mol CO (56 g) ve 4 mol H2 (8 g) tam 2 mol (64 g) kuramsal ürün verir; % verim = (48 / 64) x 100 = %75\'tir.'),
  ('Yeşil kimyanın 11. ilkesi olan "Kirliliğin önlenmesi için gerçek zamanlı analiz" endüstriyel reaktörlerde neyi sağlamayı amaçlar?', 'Tehlikeli yan ürünler oluşmadan önce süreci anlık izleyip kontrol etmeyi', ['Üretim bittikten aylar sonra atık barajlarından numune toplamayı', 'Sadece nihai ürün ambalajlandıktan sonra kalite kontrol testi yapmayı', 'Fabrika bacalarındaki filtreleri yılda bir kez tartarak raporlamayı'], 'Süreç içi (in-process) gerçek zamanlı izleme, sıcaklık veya derişim sapmalarını anında yakalayarak istenmeyen toksik yan ürün oluşumunu engeller.'),
  ('Organik sentezlerde uçucu organik çözücüler (VOC) yerine "iyonik sıvıların" yeşil çözücü adayı olarak araştırılmasının en önemli fiziksel nedeni nedir?', 'Buhar basınçlarının ihmal edilecek kadar düşük olması', ['Doğada birkaç saat içinde tamamen karbondioksit ve suya dönüşmeleri', 'Sadece hidrojen ve oksijen atomlarından meydana gelmeleri', 'Oda sıcaklığında daima gaz fazında bulunup kolay uçmaları'], 'İyonik sıvılar 100 °C\'nin altında sıvı olan tuzlardır; buhar basınçları neredeyse sıfır olduğundan atmosfere uçucu organik bileşik salımı yapmazlar.'),
  ('Enzimlerin (biyokatalizörlerin) geleneksel ağır metal katalizörlerine kıyasla yeşil kimya açısından sunduğu en büyük üstünlük aşağıdakilerden hangisidir?', 'Ilımlı pH ve sıcaklıklarda yüksek bölge ve enantiyoseçicilik göstermeleri', ['Yalnızca 400 °C üzerindeki susuz ortamlarda kararlı kalabilmeleri', 'Tepkime sonunda toksik ağır metal çamuru oluşturarak çökmeleri', 'Koruyucu grup kullanımını zorunlu kılarak yan ürün sayısını artırmaları'], 'Enzimler sulu ortamda, oda sıcaklığına yakın koşullarda yüksek seçicilikle çalışır, koruyucu grup ihtiyacını ortadan kaldırır ve biyobozunurdur.'),
  ('Glikozun (C6H12O6, MA: 180 g/mol) fermantasyonuyla C6H12O6 -> 2 C2H5OH (MA: 46 g/mol) + 2 CO2 (MA: 44 g/mol) tepkimesine göre biyoetanol üretildiğinde atom ekonomisi yaklaşık yüzde kaçtır?', '%51,1', ['%25,6', '%48,9', '%100'], '180 g glikozdan 2 x 46 = 92 g etanol oluştuğundan atom ekonomisi (92 / 180) x 100 ≈ %51,1 olur; kalan kütle CO2 yan ürününe gider.'),
  ('Geleneksel ısıtma (yağ banyosu veya ısıtıcı manto) yerine mikrodalga destekli organik sentez kullanılması yeşil kimyanın öncelikle hangi ilkesine hizmet eder?', 'Enerji verimliliği için tasarım', ['Atıkların yakılarak bertaraf edilmesi', 'Halojenli çözücü kullanımının artırılması', 'Türevlendirme basamaklarının çoğaltılması'], 'Mikrodalga ışıması enerjisini doğrudan dipol momenti olan reaktif/çözücü moleküllerine aktararak tepkime süresini saatlerden dakikalara indirir ve enerji tasarrufu sağlar.'),
  ('Mısır nişastası fermantasyonundan elde edilen laktik asit ve biyoetanolün esterleşmesiyle üretilen, boya sökücü ve temizleyici olarak klorlu çözücülerin yerini alan biyobozunur yeşil çözücü hangisidir?', 'Etil laktat', ['Benzen', 'Kloroform', 'N,N-Dimetilformamid'], 'Etil laktat yenilenebilir kaynaklardan üretilen, %100 biyobozunur, düşük toksisiteli ve yüksek çözme gücüne sahip yeşil bir ester çözücüdür.'),
  ('Demir cevherinin yüksek fırında Fe2O3 (160 g/mol) + 3 CO (28 g/mol) -> 2 Fe (56 g/mol) + 3 CO2 (44 g/mol) tepkimesiyle indirgenmesinde saf demir (Fe) eldesinin atom ekonomisi yaklaşık yüzde kaçtır?', '%45,9', ['%70,0', '%54,1', '%35,0'], 'Hedef ürün 2 mol Fe = 112 g; girenlerin toplam kütlesi 160 + (3 x 28) = 244 g olduğundan atom ekonomisi (112 / 244) x 100 ≈ %45,9 bulunur.'),
  ('Kağıt hamuru ağartma işlemlerinde elementel klor gazı (Cl2) yerine hidrojen peroksit (H2O2) ve TAML aktivatörlerinin kullanılması hangi tehlikeli yan ürün grubunun oluşumunu engeller?', 'Klorlu dioksinler ve furanlar', ['Soygaz bileşikleri ve azot gazı', 'Kalsiyum karbonat ve silika', 'Su buharı ve oksijen gazı'], 'Klorla ağartma ahşaptaki ligninle tepkimeye girerek kalıcı ve kanserojen poliklorlu dibenzodioksinler oluşturur; H2O2 ise yalnızca su ve oksijene ayrışır.'),
  ('Bir kimyasal süreçte 100 kg reaktif karışımından 80 kg hedef ürün ve 20 kg geri dönüştürülemeyen yan ürün elde edilmiştir. Süreçte ayrıca 120 kg çözücü kullanılmış ve bu çözücünün %90\'ı geri kazanılmıştır. Bu sürecin E-faktörü kaçtır?', '0,40', ['1,75', '0,25', '1,50'], 'Atık miktarı = 20 kg yan ürün + (120 kg x %10 kayıp çözücü = 12 kg) = 32 kg toplam atık. E-faktörü = 32 kg / 80 kg = 0,40 olur.'),
  ('Süperkritik su (T > 374 °C, P > 218 atm) normal koşullardaki sıvı suya göre çözücülük davranışı açısından nasıl bir değişim gösterir?', 'Dielektrik sabiti düşerek apolar organik bileşikleri iyi çözen bir ortama dönüşür', ['Polaritesi aşırı artarak yalnız iyonik tuzları çözen bir elektrolit haline gelir', 'Hidrojen bağları güçlenerek oda sıcaklığındaki buz kristali yapısını alır', 'Yüzey gerilimi sonsuza yaklaşarak hiçbir gazla karışmayan bir sıvı olur'], 'Süperkritik koşullarda suyun hidrojen bağı ağı zayıflar ve dielektrik sabiti organik çözücülerin seviyesine düşer; bu özellik "süperkritik su oksidasyonu" ile toksik organik atıkların imhasında kullanılır.'),
  ('Propen (C3H6, MA: 42 g/mol), amonyak (NH3, MA: 17 g/mol) ve oksijenin (O2, MA: 32 g/mol) 2 C3H6 + 2 NH3 + 3 O2 -> 2 C3H3N (MA: 53 g/mol) + 6 H2O (MA: 18 g/mol) tepkimesiyle akrilonitril (C3H3N) üretiminde atom ekonomisi yaklaşık yüzde kaçtır?', '%49,5', ['%72,6', '%84,0', '%33,1'], 'Hedef ürün kütlesi 2 x 53 = 106 g; girenlerin toplam kütlesi (2 x 42) + (2 x 17) + (3 x 32) = 84 + 34 + 96 = 214 g. Atom ekonomisi = (106 / 214) x 100 ≈ %49,5\'tir.'),
  ('Yeşil kimyada katalizör verimliliğini değerlendirmek için kullanılan "Çevrim Sayısı" (Turnover Number - TON) neyi ifade eder?', 'Bir mol katalizörün etkinliğini yitirmeden önce ürüne dönüştürdüğü reaktif mol sayısını', ['Tepkime kabının dakikadaki mekanik karıştırma devir sayısını', 'Elde edilen ürünün saflaştırılması için gereken kristallendirme sayısını', 'Fabrikadaki atık çözücü varillerinin yıllık taşınma sayısını'], 'TON değeri ne kadar yüksekse çok az miktarda katalizörle o kadar fazla ürün sentezlenebilir, bu da metal tüketimini ve kalıntı atığını azaltır.'),
  ('Biyokütle kaynaklı 2-metiltetrahidrofuran (2-MeTHF), geleneksel tetrahidrofuran (THF) çözücüsüne kıyasla ayırma basamağında hangi ek avantajı sunar?', 'Suyla sınırlı karışması sayesinde ek organik çözücü gerektirmeden faz ayrımı sağlaması', ['Suyun içinde her oranda çözünerek damıtmayı imkansız hale getirmesi', 'Oda sıcaklığında katı olduğu için süzgeç kağıdında kalması', 'Yoğunluğunun cıvadan büyük olması nedeniyle reaktör dibine çökmesi'], 'Mısır koçanı ve şeker kamışı küspesinden (furfural üzerinden) üretilen 2-MeTHF suyla azeotrop/faz ayrımı yaptığı için ekstraksiyonda ayrıca diklorometan kullanımına gerek bırakmaz.'),
  ('Bir kimyasal sentezin yeşil kimya performansını değerlendirirken kullanılan "Etkin Kütle Verimi" (Effective Mass Yield) geleneksel % verimden hangi yönüyle ayrılır?', 'Hedef ürün kütlesinin süreçte kullanılan zararsız olmayan (toksik/tehlikeli) tüm maddelerin kütlesine oranlanmasıyla', ['Yalnızca gaz fazındaki yan ürünlerin hacimlerini hesaba katmasıyla', 'Katalizörün atom numarasını kuramsal verimle çarpmasıyla', 'Sıcaklığın Kelvin cinsinden değerini reaktif kütlesine bölmesiyle'], 'Etkin kütle verimi reaktif, çözücü ve yardımcı maddeler içindeki çevresel açıdan tehlikeli bileşenlerin toplam kütlesini paydaya koyarak toksisite boyutunu hesaba katar.'),
  ('Maleik anhidrit (C4H2O3, MA: 98 g/mol) benzenin (C6H6, MA: 78 g/mol) yükseltgenmesiyle (2 C6H6 + 9 O2 -> 2 C4H2O3 + 4 CO2 + 4 H2O) ya da n-bütanın (C4H10, MA: 58 g/mol) yükseltgenmesiyle (2 C4H10 + 7 O2 -> 2 C4H2O3 + 8 H2O) üretilebilir (O2 MA: 32 g/mol). n-Bütan yönteminin benzen yöntemine göre üstünlüğü nedir?', 'Karbon atomu kaybını (CO2 yan ürününü) önleyip atom ekonomisini ~%44,1\'den ~%57,6\'ya çıkarması', ['Yan ürün olarak su yerine hidrojen gazı üreterek %100 atom ekonomisi sağlaması', 'Kanserojen olmayan benzen yerine kanserojen n-bütan kullanımını teşvik etmesi', 'Oksijen gazına olan stokiyometrik ihtiyacı tamamen ortadan kaldırması'], 'Benzen yönteminde 6 karbonlu halkadan 2 karbon CO2 olarak atılır (AE = 196 / 444 ≈ %44,1) ve benzen kanserojendir; 4 karbonlu n-bütanda karbon iskeleti korunur (AE = 196 / 340 ≈ %57,6).'),
  ('Gemi gövdelerinde deniz canlılarının yapışmasını önlemek (antifouling) amacıyla kalıcı ve zehirli tribütilkalay (TBT) bileşikleri yerine "Sea-Nine 211" adlı biyositin geliştirilmesi hangi yeşil kimya ilkesinin ödüllü bir örneğidir?', 'Bozunur tasarım ve daha güvenli kimyasal ürün tasarımı', ['Süperkritik karbondioksit ile kuru temizleme tasarımı', 'Yüksek basınçlı amonyak sentezi optimizasyonu', 'Polietilen tereftalat şişelerin mekanik kırılması'], 'Sea-Nine 211 deniz suyunda hızla biyolojik olarak zararsız bileşiklere parçalanır, besin zincirinde birikmez ve TBT\'nin yarattığı ağır ekotoksisiteyi önler.'),
  ('Kireçtaşından ve tuzdan Solvay yöntemiyle sodyum karbonat üretiminde net denklem CaCO3 (100) + 2 NaCl (58,5) -> Na2CO3 (106) + CaCl2 (111) şeklindedir. Na2CO3 üretimi için bu sürecin atom ekonomisi yaklaşık yüzde kaçtır?', '%48,8', ['%51,2', '%75,4', '%90,6'], 'Girenlerin toplam mol kütlesi 100 + (2 x 58,5) = 217 g/mol, hedef ürün Na2CO3 106 g/mol olduğundan atom ekonomisi (106 / 217) x 100 ≈ %48,8 hesaplanır.'),
  ('Sürekli akış kimyası (flow chemistry) mikroreaktörlerinin geleneksel büyük kesikli (batch) kazanlara göre yeşil kimya açısından sağladığı güvenlik avantajı nedir?', 'Yüksek yüzey/hacim oranı sayesinde üstün ısı aktarımı sağlayıp kontrolsüz patlama riskini düşürmesi', ['Reaktör içinde tonlarca tehlikeli ara ürünü aynı anda depolamaya izin vermesi', 'Soğutma ihtiyacını artırmak için çözücü kaynama noktasını düşürmesi', 'Tepkime hızını yavaşlatarak zehirli gazların ortama yayılmasını kolaylaştırması'], 'Mikrokanallı akış reaktörlerinde anlık reaktif hacmi çok küçüktür ve ısı transferi çok hızlıdır; bu durum 12. ilke (kaza önleme) ve 6. ilke (enerji verimliliği) açısından büyük üstünlük sağlar.'),
  ('Biyodizel üretimi sırasında trigliseritlerin transesterleşmesi sonucunda hedef ürün olan yağ asidi metil esterlerinin yanında oluşan ve yeşil kimya kapsamında katma değerli kimyasallara dönüştürülen ana yan ürün nedir?', 'Gliserol', ['Benzen', 'Polivinil klorür', 'Sodyum sülfat'], 'Her 10 kg biyodizel üretiminde yaklaşık 1 kg ham gliserol yan ürünü çıkar; bu gliserolün propilen glikol veya epiklorohidrin üretiminde hammadde olarak kullanılması süreci daha yeşil yapar.'),
  ('Ultrasonik ses dalgalarının (sonokimya) sıvı ortamdaki kimyasal tepkimeleri hızlandırmasının temel fizikokimyasal mekanizması nedir?', 'Akustik kavitasyon ile oluşan mikro kabarcıkların çökerek yerel yüksek sıcaklık ve basınç yaratması', ['Ses dalgalarının atom çekirdeklerindeki proton sayısını kalıcı olarak değiştirmesi', 'Çözücü moleküllerinin kovalent bağlarını dondurarak kristalleştirmesi', 'Reaktör dışından ortama ağır metal iyonları pompalaması'], 'Sonokimyada kavitasyon kabarcıklarının anlık çöküşü mikro ölçekte yüksek enerji yoğunluğu sağlayarak dışarıdan uzun süreli ısıtma yapmadan tepkimeleri hızlandırır.'),
  ('Amonyak üretimi için Haber-Bosch tepkimesinde N2 (28 g/mol) + 3 H2 (2 g/mol) -> 2 NH3 (17 g/mol) denklemi geçerlidir. Reaktöre 28 kg N2 ve 6 kg H2 beslendiğinde tek geçişte 8,5 kg NH3 elde ediliyorsa tepkimenin atom ekonomisi ve tek geçiş % verimi nedir?', '%100 ve %25', ['%25 ve %100', '%50 ve %25', '%100 ve %50'], 'Yan ürün olmadığından atom ekonomisi %100\'dür. Kuramsal verim 28 + 6 = 34 kg NH3 olup tek geçiş % verimi (8,5 / 34) x 100 = %25\'tir (kalan gazlar döngüye sokulur).'),
  ('Faz transfer katalizörleri (örneğin kuaterner amonyum tuzları), birbirleriyle karışmayan su ve organik faz arasındaki tepkimelerde hangi yeşil kimya katkısını sağlar?', 'Toksik aprotik polar çözücülere (DMF, DMSO) gerek kalmadan sulu fazdaki iyonları organik reaktifle buluşturması', ['Sulu fazı tamamen buharlaştırarak reaktör basıncını 200 atmosfere çıkarması', 'Tepkime sonunda ürünün yapısına kalıcı olarak brom atomları bağlaması', 'Reaksiyonun yalnızca kriyojenik sıcaklıklarda yürümesini sağlaması'], 'Faz transfer katalizi sayesinde NaCN veya NaOH gibi ucuz inorganik tuzlar sulu fazda çözülürken, DMF/DMSO gibi geri kazanımı çok zor çözücüler kullanılmadan tepkime yüksek hızda yürür.'),
  ('Kalsiyum oksit (CaO, 56 g/mol) ile amonyum klorür (NH4Cl, 53,5 g/mol) ısıtılarak CaO + 2 NH4Cl -> 2 NH3 (17 g/mol) + CaCl2 (111 g/mol) + H2O (18 g/mol) tepkimesiyle laboratuvarda amonyak gazı (NH3) elde edildiğinde atom ekonomisi yaklaşık yüzde kaçtır?', '%20,9', ['%41,7', '%34,0', '%68,1'], 'Hedef ürün 2 mol NH3 = 34 g; girenlerin toplam kütlesi 56 + (2 x 53,5) = 163 g olduğundan atom ekonomisi (34 / 163) x 100 ≈ %20,9 bulunur.'),
  ('Süperkritik CO2 yalnızca apolar ve düşük polariteli bileşikleri iyi çözdüğü için daha polar organik molekülleri özütlemek gerektiğinde sisteme az miktarda ne eklenir?', 'Etanol veya su gibi zararsız bir yardımcı çözücü', ['Kanserojen benzen ve karbon tetraklorür karışımı', 'Metalik cıva ve kurşun nitrat süspansiyonu', 'Sıvılaştırılmış fosgen ve klor gazı'], 'Süperkritik CO2\'ye %1-5 oranında etanol gibi yeşil bir yardımcı çözücü eklenmesi akışkanın polaritesini ve hidrojen bağı kapasitesini artırarak polar maddelerin de çözünmesini sağlar.'),
  ('Stratosferde serbest klor radikalinin ozon (O₃) ile girdiği ilk tepkimede oluşan ürünler hangileridir?', 'Klor monoksit ve oksijen', ['Hidroklorik asit ve azot', 'Karbon monoksit ve su buharı', 'Klor gazı ve hidrojen peroksit'], 'Cl· + O₃ → ClO· + O₂ tepkimesiyle ozon parçalanır ve klor monoksit radikali oluşur.'),
  ('CFC\'lerin yerine geliştirilen hidroflorokarbon (HFC) gazlarının ozon tabakasını inceltmemesinin temel kimyasal nedeni nedir?', 'Yapılarında klor veya brom bulunmaması', ['Suda çok yüksek oranda çözünebilmeleri', 'Atmosferde asla ısı tutmamaları', 'Sadece sıvı hâlde depolanabilmeleri'], 'HFC\'ler karbon, hidrojen ve flor içerir; ozonu katalitik olarak parçalayan klor veya brom atomu taşımazlar.'),
  ('Chapman mekanizmasına göre stratosferde doğal ozon oluşumu hangi olayla başlar?', 'O₂ molekülünün UV-C ile atomlara ayrılması', ['CO₂ molekülünün su buharı ile birleşmesi', 'N₂ gazının şimşek enerjisiyle parçalanması', 'CH₄ gazının oksijenle yanma tepkimesi'], 'O₂ + UV (<242 nm) → 2 O· tepkimesiyle oluşan oksijen atomları başka O₂ molekülleriyle birleşerek O₃ üretir.'),
  ('Fotokimyasal sisin (Los Angeles tipi sis) oluşması için güneş ışığı yanında hangi iki öncül kirletici grubu gereklidir?', 'Azot oksitler ve uçucu organik bileşikler', ['Kükürt dioksit ve yüksek nemli kömür dumanı', 'Karbondioksit ve ağır metal tozları', 'Amonyak gazı ve kalsiyum karbonat tozu'], 'Fotokimyasal sis, özellikle yoğun trafik kaynaklı NOx ve VOC bileşiklerinin UV ışığı altında tepkimeye girmesiyle oluşur.'),
  ('Fotokimyasal sisin (Los Angeles tipi) aksine, klasik Londra tipi (sülfürlü) sisin oluşumunda temel rol oynayan kirleticiler nelerdir?', 'Kükürt dioksit ve partikül madde', ['Kloroflorokarbon ve metan gazı', 'Troposferik ozon ve karbon monoksit', 'Azot gazı ve su buharı kristalleri'], 'Londra tipi sis soğuk, nemli havalarda yüksek kükürtlü kömür yakılmasından çıkan SO₂ ve kurum partiküllerinin birikmesiyle oluşur.'),
  ('Troposferde güneş ışığı altında NO₂ gazının fotolizi sonucu doğrudan hangi iki tür oluşur?', 'NO ve oksijen atomu', ['N₂ ve karbondioksit gazı', 'HNO₃ ve hidrojen gazı', 'NH₃ ve ozon molekülü'], 'NO₂ + hν → NO + O· tepkimesiyle oluşan atomik oksijen, O₂ ile birleşerek troposferik ozon üretimini başlatır.'),
  ('Atmosferde kükürt trioksit (SO₃) gazının su buharı ile tepkimesi sonucu hangi kuvvetli asit oluşur?', 'Sülfürik asit', ['Sülfüröz asit', 'Hidrojen sülfür', 'Karbonik asit'], 'SO₃(g) + H₂O(s) → H₂SO₄(suda) tepkimesi asit yağmurlarındaki başlıca asitlerden olan sülfürik asiti üretir.'),
  ('Azot dioksit (NO₂) gazının atmosferdeki su damlacıklarıyla tepkimeye girmesiyle oluşan ana kuvvetli asit hangisidir?', 'Nitrik asit', ['Asetik asit', 'Fosforik asit', 'Hidroklorik asit'], '3 NO₂ + H₂O → 2 HNO₃ + NO tepkimesiyle asit yağmurlarına neden olan nitrik asit meydana gelir.'),
  ('Mermer ve kireç taşından yapılmış tarihi eserlerin asit yağmurlarıyla aşınmasında CaCO₃ hangi asitle tepkimeye girerek jips (CaSO₄·2H₂O) kabuğu oluşturur?', 'Sülfürik asit', ['Borik asit', 'Siyanür asidi', 'Stearik asit'], 'Sülfürik asit, kalsiyum karbonatı çözerek gözenekli ve kırılgan kalsiyum sülfat (jips) tabakasına dönüştürür.'),
  ('Termik santral bacalarından kükürt dioksit (SO₂) gazını tutmak için kullanılan baca gazı desülfürizasyonu (FGD) sisteminde yaygın olarak hangi madde kullanılır?', 'Kireç taşı bulamacı', ['Saf benzin buharı', 'Sıvı azot çözeltisi', 'Polietilen granülleri'], 'Islak yıkayıcılarda CaCO₃ veya Ca(OH)₂ bulamacı asidik SO₂ gazıyla tepkimeye girerek kalsiyum sülfit/sülfat (alçıtaşı) şeklinde kükürdü tutar.'),
  ('İçten yanmalı motorlu araçların egzozlarında bulunan üç yollu katalitik konvertör, zararlı NOx gazlarını hangi zararsız gaza indirger?', 'Azot gazı', ['Metan gazı', 'Klor gazı', 'Amonyak gazı'], 'Üç yollu katalitik konvertördeki rodyum/platin katalizörleri NOx\'i N₂\'ye indirgerken CO ve yanmamış hidrokarbonları CO₂ ve H₂O\'ya yükseltger.'),
  ('Küresel Isınma Potansiyeli (GWP) hesaplanırken referans olarak GWP değeri 1 kabul edilen gaz hangisidir?', 'Karbondioksit', ['Metan gazı', 'Diazot monoksit', 'Kükürt hekzaflorür'], 'GWP, belirli bir zaman diliminde (genellikle 100 yıl) 1 kg gazın 1 kg CO₂\'ye kıyasla tuttuğu ısı miktarını ifade eder.'),
  ('100 yıllık zaman ölçeğinde küresel ısınma potansiyeli (GWP) en yüksek olan ve yüksek gerilim şalt cihazlarında yalıtkan olarak kullanılan sera gazı hangisidir?', 'Kükürt hekzaflorür (SF₆)', ['Karbondioksit (CO₂)', 'Karbon monoksit (CO)', 'Kükürt dioksit (SO₂)'], 'SF₆ atmosferde binlerce yıl kalabilen ve 100 yıllık GWP değeri 23.000\'in üzerinde olan en güçlü sera gazlarından biridir.'),
  ('Geviş getiren çiftlik hayvanlarının sindirimi, pirinç tarlaları ve çöplüklerdeki oksijensiz çürüme hangi önemli sera gazının başlıca kaynaklarıdır?', 'Metan', ['Ozon gazı', 'Kükürt trioksit', 'Hidrojen klorür'], 'Anaerobik mikroorganizmalar organik maddeleri oksijensiz parçalarken yüksek GWP değerine sahip metan (CH₄) gazı üretir.'),
  ('Tarımda azotlu gübrelerin aşırı kullanımı sonucu topraktaki nitrifikasyon ve denitrifikasyon süreçleriyle salınan güçlü sera gazı hangisidir?', 'Diazot monoksit (N₂O)', ['Karbon monoksit (CO)', 'Kükürt hekzaflorür (SF₆)', 'Hidrojen sülfür (H₂S)'], 'Gülen gaz olarak da bilinen N₂O, 100 yıllık GWP\'si yaklaşık 273 olan güçlü bir sera gazıdır ve stratosferik ozonu da inceltir.'),
  ('PM2,5 partiküllerinin insan sağlığı açısından PM10 partiküllerinden daha tehlikeli kabul edilmesinin temel nedeni nedir?', 'Akciğer alveollerine ve kana ulaşabilmeleri', ['Gözle kolayca görülüp elle toplanabilmeleri', 'Yalnızca burun kıllarında takılı kalmaları', 'Suda çözündüklerinde tatlı su üretmeleri'], 'Çok küçük çapları sayesinde PM2,5 partikülleri üst solunum yolu filtrelerini geçerek derin akciğer alveollerine ve dolaşım sistemine girebilir.'),
  ('İnşaat kazıları, taş ocakları ve rüzgârla kalkan yol tozları daha çok hangi boyut aralığındaki partikül maddelerin kaynağını oluşturur?', 'PM10', ['Gaz hâlindeki soy gazlar', 'Atom altı temel parçacıklar', 'Yalnızca sıvı su damlacıkları'], 'Mekanik kırma, rüzgâr erozyonu ve yol tozları ağırlıklı olarak 2,5 ile 10 mikrometre arasındaki kaba partikülleri (PM10) oluşturur.'),
  ('Fosil yakıtların eksik yanması sonucu oluşan ve kandaki hemoglobine oksijenden 200 kattan fazla ilgiyle bağlanan zehirli gaz hangisidir?', 'Karbon monoksit', ['Karbondioksit gazı', 'Azot molekülü', 'Metan bileşiği'], 'CO, hemoglobine sıkıca bağlanarak karboksihemoglobin oluşturur ve dokulara oksijen taşınmasını engeller.'),
  ('Atmosferde ikincil partikül madde (örneğin amonyum sülfat) oluşumu hangi iki gaz grubunun kimyasal tepkimesiyle gerçekleşir?', 'Amonyak ve asidik gazlar', ['Soy gazlar ve oksijen', 'Azot gazı ve su buharı', 'Hidrojen gazı ve metan'], 'Tarımdan çıkan bazik NH₃ gazı, atmosferde H₂SO₄ ve HNO₃ ile tepkimeye girerek (NH₄)₂SO₄ ve NH₄NO₃ gibi ince PM2,5 aerosollerini oluşturur.'),
  ('Zemin altındaki kayaçlardan sızarak bodrum katlarda birikebilen ve akciğer kanseri riskini artıran doğal radyoaktif gaz hangisidir?', 'Radon', ['Neon gazı', 'Helyum gazı', 'Kripton gazı'], 'Uranyumun doğal radyoaktif bozunma zincirinde oluşan radon (Rn), renksiz ve kokusuz bir iç ortam hava kirleticisidir.'),
  ('Atmosferde bulunan hidroksil radikali (·OH) neden sıklıkla "atmosferin deterjanı" olarak adlandırılır?', 'Birçok kirleticiyi yükseltgeyerek temizlemesi', ['Yağmur sularını köpüklü hâle getirmesi', 'Sadece çamaşır fabrikalarından yayılması', 'Ozon tabakasını doğrudan onarması'], 'Troposferdeki ·OH radikalleri CH₄, CO ve VOC gibi kirleticilerle hızlı tepkimeye girerek atmosferden uzaklaştırılmalarını başlatır.'),
  ('Geçici sert suya sahip bir çaydanlık kaynatıldığında dipte kireç taşı (CaCO₃) oluşumunu gösteren doğru tepkime hangisidir?', 'Ca(HCO₃)₂ → CaCO₃ + H₂O + CO₂', ['CaCl₂ + H₂O → CaO + 2 HCl', 'Na₂CO₃ → Na₂O + CO₂', 'MgSO₄ → MgS + 2 O₂'], 'Isıtılan kalsiyum bikarbonat bozunarak çözünmeyen CaCO₃ katısını, suyu ve CO₂ gazını açığa çıkarır.'),
  ('Kaynatma ile giderilemeyen kalıcı su sertliği, Ca²⁺ ve Mg²⁺ iyonlarının suda hangi anyonlarla birlikte bulunmasından kaynaklanır?', 'Sülfat ve klorür', ['Yalnızca bikarbonat', 'Hidroksit ve karbonat', 'Asetat ve format'], 'Kalıcı sertlik, kalsiyum ve magnezyumun sülfat (SO₄²⁻) ve klorür (Cl⁻) tuzlarından oluşur; bu tuzlar kaynatmayla çökmez.'),
  ('Kalıcı sertliği gidermek için suya çamaşır sodası (Na₂CO₃) eklendiğinde gerçekleşen temel kimyasal olay nedir?', 'Ca²⁺ ve Mg²⁺\'nin karbonat olarak çökmesi', ['Sodyum iyonlarının buharlaşarak uçması', 'Suyun pH değerinin 2\'ye düşmesi', 'Klorür iyonlarının gaza dönüşmesi'], 'Na₂CO₃ suya CO₃²⁻ iyonu sağlar; bu iyonlar Ca²⁺ ve Mg²⁺ ile suda çözünmeyen CaCO₃ ve MgCO₃ çökeltisi oluşturur.'),
  ('Evsel ve endüstriyel su yumuşatma cihazlarındaki katyon değiştirici reçineler sert suyu nasıl yumuşatır?', 'Ca²⁺ ve Mg²⁺ yerine Na⁺ verir', ['Suyun tüm oksijenini dışarı atar', 'Kalsiyum iyonlarını karbona dönüştürür', 'Suyu kaynatarak buharlaştırır'], 'İyon değiştirici reçineler sudaki sertlik yapan Ca²⁺ ve Mg²⁺ iyonlarını tutarken yerlerine sertlik yapmayan Na⁺ iyonlarını salar.'),
  ('Sentetik deterjanların sert sularda sabunlara kıyasla temizleme gücünü koruyabilmesinin kimyasal sebebi nedir?', 'Sülfonat tuzlarının Ca²⁺ ile çökmemesi', ['Deterjanların yalnızca soğuk suda çalışması', 'Deterjanların içinde hiç karbon bulunmaması', 'Sert sudaki tüm iyonları buharlaştırması'], 'Deterjanlardaki alkilbenzen sülfonat gruplarının kalsiyum ve magnezyum tuzları suda çözünür kaldığından çökelek oluşmaz.'),
  ('İçme sularının dezenfeksiyonunda klorlamaya alternatif olarak organik kalıntı bırakmayan ve çok güçlü yükseltgeyici etki gösteren gaz hangisidir?', 'Ozon', ['Helyum gazı', 'Metan gazı', 'Azot molekülü'], 'Ozon (O₃), mikroorganizmaları hızla yok eder ve suda klorlu yan ürünler bırakmadan tekrar O₂ gazına dönüşür.'),
  ('Ötrofikasyon sürecinde başlangıçta fotosentez yapan alglerin aşırı çoğalmasına rağmen suyun derinliklerinde oksijenin hızla tükenmesinin nedeni nedir?', 'Ölen alglerin aerobik bakterilerce ayrıştırılması', ['Alglerin sudaki tüm oksijeni katılaştırması', 'Güneş ışığının suyu tamamen buharlaştırması', 'Balıkların oksijeni azota dönüştürmesi'], 'Ölen alg biyokütlesi dibe çöktüğünde bunları parçalayan aerobik ayrıştırıcı bakteriler sudaki çözünmüş O₂\'yi hızla tüketir.'),
  ('Bir atık su örneğindeki organik kirlilik yükünü ölçmek için kullanılan BOİ (Biyokimyasal Oksijen İhtiyacı) parametresi neyi gösterir?', 'Organik maddeleri ayrıştırmak için gereken O₂ miktarını', ['Suyun kaynama noktasındaki sıcaklık artışını', 'Suda çözünmüş toplam tuz ve mineral kütlesini', 'Atık suyun güneş ışığını yansıtma yüzdesini'], 'BOİ (genellikle 5 günlük BOİ₅), mikroorganizmaların sudaki biyobozunur organik maddeleri ayrıştırırken tükettikleri çözünmüş oksijen miktarıdır.'),
  ('Suyun sıcaklığının artması (termal kirlilik) sudaki canlı yaşamını çözünmüş oksijen açısından nasıl etkiler?', 'Gazların çözünürlüğü azaldığı için O₂ düşer', ['Oksijenin suda çözünürlüğü iki katına çıkar', 'Sıcaklık gaz çözünürlüğünü hiç etkilemez', 'Su molekülleri kendiliğinden O₂ gazına ayrışır'], 'Gazların sıvılardaki çözünürlüğü ekzotermiktir; su ısındıkça çözünmüş O₂ derişimi azalırken canlıların metabolik oksijen ihtiyacı artar.'),
  ('Japonya\'daki Minamata Körfezi\'nde ciddi nörolojik zehirlenmelere (Minamata hastalığı) yol açan ve besin zincirinde biriken ağır metal türevi hangisidir?', 'Metilciva', ['Kalsiyum karbonat', 'Demir(III) oksit', 'Magnezyum sülfat'], 'Endüstriyel atıklarla denize karışan cıvanın bakterilerce dönüştürüldüğü metilciva (CH₃Hg⁺), balıklarda biyobirikime uğrayarak ağır zehirlenmelere yol açmıştır.'),
  ('Japonya\'da "Itai-Itai" (canım yanıyor) hastalığına ve şiddetli kemik erimesine neden olan ağır metal kirleticisi hangisidir?', 'Kadmiyum', ['Potasyum', 'Magnezyum', 'Silisyum'], 'Maden atıklarından pirinç tarlalarına karışan kadmiyum (Cd²⁺), böbrek hasarına ve kemiklerde kalsiyum kaybıyla ağrılı kırıklara neden olmuştur.'),
  ('Endüstriyel atık sulardan Pb²⁺, Cd²⁺ ve Cu²⁺ gibi ağır metal iyonlarını uzaklaştırmak için yaygın olarak kullanılan kimyasal çökeltme yönteminde suya genellikle ne eklenir?', 'Baz eklenerek metal hidroksit çöktürülür', ['Kuvvetli asit eklenerek pH 1\'e düşürülür', 'Saf etanol eklenerek metaller buharlaştırılır', 'Şeker eklenerek metaller gaza dönüştürülür'], 'Suyun pH\'ı kireç veya NaOH ile yükseltildiğinde birçok ağır metal suda çözünmeyen hidroksitler [M(OH)₂] hâlinde çöker.'),
  ('Aktif karbonun su arıtımında eser organik kirleticileri, koku maddelerini ve bazı ağır metalleri tutma mekanizması hangisidir?', 'Adsorpsiyon', ['Nükleer fisyon', 'Kuru buzlaştırma', 'Asit-baz nötrleşmesi'], 'Aktif karbon, son derece geniş gözenekli yüzey alanı sayesinde kirletici molekülleri yüzeyine fiziksel/kimyasal adsorpsiyonla bağlar.'),
  ('Yeraltı sularında arsenik (As) kirliliğinin doğal kaynaklı olarak yüksek düzeylere çıkmasının başlıca sebebi nedir?', 'Arsenik içeren kayaç minerallerinin çözünmesi', ['Yağmur sularının havadan saf arsenik çekmesi', 'Plastik şişelerin toprakta arsenik üretmesi', 'Güneş ışığının kumu arseniğe çevirmesi'], 'Doğal pirit ve arsenopirit gibi minerallerin yeraltı suyuna çözünmesi özellikle bazı delta bölgelerinde ciddi arsenik kirliliği yaratır.'),
  ('Atık su arıtma tesislerinde ikincil (biyolojik) arıtma aşamasının temel amacı nedir?', 'Çözünmüş organik maddeleri mikroorganizmalarla parçalamak', ['İri plastik şişeleri ızgaralarla tutmak', 'Suyu buharlaştırıp tamamen tuz elde etmek', 'Ağır metalleri mıknatısla ayırmak'], 'Aktif çamur gibi biyolojik arıtma süreçlerinde aerobik bakteriler sudaki çözünmüş organik kirliliği CO₂, H₂O ve biyokütleye dönüştürür.'),
  ('A + B → C şeklinde yalnızca tek bir ana ürün veren bir katılma tepkimesinin teorik atom ekonomisi yüzde kaçtır?', '%100', ['%50,0', '%25,0', '%75,0'], 'Katılma ve düzenlenme tepkimelerinde girenlerin tüm atomları hedeflenen tek ürüne geçtiği için yan ürün oluşmaz ve teorik atom ekonomisi %100\'dür.'),
  ('Yeşil kimyada yüksek yüzde verime (%95 gibi) sahip bir tepkime neden yine de çevre açısından verimsiz sayılabilir?', 'Atom ekonomisi düşükse çok yan ürün üretir', ['Yüksek verimli tepkimeler asla laboratuvarda yürümez', 'Yüzde verim sadece sıcaklık ölçümüyle ilgilidir', 'Yüksek verim her zaman radyoaktif madde açığa çıkarır'], 'Bir tepkime yüksek verimle gerçekleşse bile stokiyometrik olarak büyük kütleli yan ürünler üretiyorsa atom ekonomisi düşük ve atık miktarı yüksek olur.'),
  ('Yeşil kimya ilkelerine göre stokiyometrik reaktifler yerine seçici katalizörlerin tercih edilmesinin başlıca avantajı nedir?', 'Küçük miktarda tekrar kullanılıp atığı azaltmaları', ['Tepkimenin ürün verimini her zaman sıfırlamaları', 'Tepkimeye girip tamamen zararlı atığa dönüşmeleri', 'Sadece 1000 °C\'nin üzerinde çalışabilmeleri'], 'Katalizörler aktivasyon enerjisini düşürerek daha ılımlı koşullarda çalışmayı sağlar, tükenmeden birçok çevrim yürütür ve yan ürünleri azaltır.'),
  ('Geleneksel sentezlerde organik çözücüler yerine yeşil çözücü olarak kahveden kafein çekiminde ve kuru temizlemede kullanılan madde hangisidir?', 'Süperkritik karbondioksit', ['Sıvı karbon tetraklorür', 'Benzen ve toluen karışımı', 'Kloroform çözeltisi'], 'Süperkritik CO₂ (31 °C ve 73 atm üzerinde) zehirsizdir, yanıcı değildir ve basınç düşürüldüğünde üründen kalıntı bırakmadan gaz olarak uzaklaşır.'),
  ('Yeşil kimyada "türevlerin azaltılması" ilkesi kimyasal sentezde hangi gereksiz uygulamalardan kaçınılmasını önerir?', 'Koruyucu grup takma ve çıkarma adımlarından', ['Tepkime hızını ölçme işlemlerinden', 'Ürünlerin saf hâlde tartılmasından', 'Tepkimede su kullanılmasından'], 'Geçici koruyucu (bloke edici) gruplar eklemek ve sonra sökmek ekstra reaktif, çözücü ve enerji tüketerek atık miktarını artırır.'),
  ('Klasik kimyasal analizlere kıyasla "Kirliliği Önlemek İçin Gerçek Zamanlı Analiz" ilkesinin endüstrideki önemi nedir?', 'Tehlikeli yan ürün oluşmadan süreci anlık izlemek', ['Fabrika kapandıktan yıllar sonra numune almak', 'Yalnızca son ürün paketlendikten sonra tartmak', 'Tepkime sıcaklığını hiç ölçmeden tahmini çalışmak'], 'Hat içi (in-line) sensörlerle tepkimenin anlık izlenmesi, sapmaları erken fark ederek zararlı yan ürünlerin ve atık partilerin oluşmasını engeller.'),
  ('PLA (Polilaktik asit) polimerinin tekrar eden monomer birimi hangi organik asitten türetilir?', 'Laktik asit', ['Sülfürik asit', 'Benzoik asit', 'Hidroklorik asit'], 'Karbonhidratların bakteriyel fermantasyonuyla üretilen 2-hidroksipropanoik asit (laktik asit), PLA sentezinin temel yapı taşıdır.'),
  ('Bazı bakterilerin besin fazlalığı ve azot/fosfor kısıtlaması altında hücre içi enerji deposu olarak doğrudan sentezlediği biyobozunur polyester ailesi hangisidir?', 'Polihidroksialkanoatlar (PHA)', ['Polikarbonatlar (PC)', 'Poliüretanlar (PU)', 'Polipropilenler (PP)'], 'PHA\'lar (örneğin PHB) mikroorganizmalar tarafından doğal olarak sentezlenen, hem toprakta hem de deniz ortamında biyobozunabilen polimerlerdir.'),
  ('PLA (Polilaktik asit) ambalajların soğuk deniz suyunda veya ev bahçesinde neden hızla bozunamadığı nasıl açıklanır?', 'Yüksek sıcaklık ve nemli endüstriyel kompost ister', ['İçinde yüksek oranda ağır metal kurşun bulunur', 'Yalnızca güneşin olmadığı karanlıkta bozunur', 'Kimyasal yapısı elmas kristali kadar serttir'], 'PLA\'nın camsı geçiş sıcaklığı ~60 °C olduğundan hızlı hidroliz ve mikrobiyal bozunma için ~55-60 °C sıcaklık sağlayan endüstriyel kompost tesisleri gerekir.'),
  ('Petrol kökenli olmasına rağmen ana zincirindeki ester bağları nedeniyle biyobozunur olan ve dikiş ipliği ile ambalajda kullanılan sentetik polimer hangisidir?', 'Polikaprolakton (PCL)', ['Yüksek yoğunluklu polietilen (HDPE)', 'Polistiren (PS)', 'Polivinil klorür (PVC)'], 'PCL ve PBAT gibi bazı fosil kaynaklı polimerler yapılarındaki hidrolizlenebilir ester bağları sayesinde biyobozunur özellik gösterir.'),
  ('Geri dönüşüm kodu "3" olan PVC plastik atıklarının kontrolsüz yakılması çevre ve insan sağlığı için neden özellikle tehlikelidir?', 'HCl gazı ve dioksinler açığa çıkarabilir', ['Yalnızca saf oksijen ve su buharı üretir', 'Yanma sırasında havadaki CO₂\'yi tamamen emer', 'Ortamdaki tüm ağır metalleri buharlaştırıp yok eder'], 'PVC\'nin yapısındaki klor atomları düşük sıcaklıklı ve eksik yanmada aşındırıcı HCl gazı ile son derece toksik poliklorlu dioksin/furanların oluşmasına yol açar.'),
  ('Karışık plastik atıkların geri dönüşüm tesisinde su tankına atıldığında PP (0,90 g/cm³) ve HDPE\'nin (0,95 g/cm³) PET (1,38 g/cm³) ve PVC\'den (1,35 g/cm³) ayrılma yöntemi nedir?', 'Yoğunluk farkıyla yüzdürme-çöktürme', ['Yüksek voltajlı elektroliz işlemi', 'Kuvvetli asitte tamamen çözme', 'Sadece mıknatısla ayırma'], 'Suyun yoğunluğu 1,00 g/cm³ olduğundan PP ve HDPE suda yüzerken PET ve PVC dibe çöker; böylece plastikler fiziksel olarak ayrıştırılır.'),
  ('Plastik geri dönüşümünde "mekanik geri dönüşüm" ile "kimyasal (ileri) geri dönüşüm" arasındaki temel fark nedir?', 'Kimyasal geri dönüşüm polimeri monomerlere parçalar', ['Mekanik geri dönüşüm plastiği her zaman gazlaştırır', 'Kimyasal geri dönüşüm yalnızca kağıt atıklara uygulanır', 'Mekanik geri dönüşümde polimer zinciri hiç eritilmez'], 'Mekanik geri dönüşümde plastik yıkanıp kırılarak tekrar eritilir; kimyasal geri dönüşümde (piroliz, glikoliz vb.) polimer bağları kırılarak monomer veya yakıt elde edilir.'),
  ('PET şişelerin mekanik geri dönüşümü tekrarlandıkça plastik kalitesinin düşmesine (downcycling) yol açan moleküler olay nedir?', 'Polimer zincirlerinin kısalması ve bozunması', ['Karbon atomlarının altına dönüşmesi', 'Plastiğin yoğunluğunun sıfıra inmesi', 'Zincirlerin sonsuz uzunluğa ulaşması'], 'Yüksek sıcaklık ve mekanik kesme kuvveti termal-mekanik bozunmaya yol açarak polimer zincirlerini kırar; mekanik dayanım ve optik berraklık azalır.'),
  ('Karışık ve kirli plastik atıkların oksijensiz ortamda yüksek sıcaklıkta (400-600 °C) ısıtılarak sıvı yağ ve gaz yakıtlara dönüştürülmesi işlemine ne ad verilir?', 'Piroliz', ['Fermantasyon', 'Klorlama', 'Pıhtılaştırma'], 'Piroliz (termal kraking), oksijensiz ortamda büyük polimer zincirlerini daha küçük hidrokarbon zincirlerine parçalayarak kimyasal hammadde veya yakıt üretir.'),
  ('Büyük plastik şişelerin ve poşetlerin denizlerde zamanla ikincil mikroplastiklere parçalanmasında en etkili çevresel faktör ikilisi nedir?', 'UV fotobozunma ve dalga aşındırması', ['Karanlık ortam ve durgun tatlı su', 'Yüksek basınçlı tuz kristalleri', 'Sadece balıkların plastikleri ısırması'], 'Güneşin UV ışınları polimer zincirlerini kırıp plastiği kırılganlaştırır; ardından dalga ve rüzgârın mekanik etkisiyle mikroplastikler oluşur.'),
  ('Kâğıt geri dönüşümünün camın aksine genellikle 5-7 döngü ile sınırlı kalmasının temel malzeme bilimi nedeni nedir?', 'Selüloz liflerinin her işlemde kısalması', ['Kâğıdın içindeki demirin paslanması', 'Kâğıdın geri dönüştürülünce cama dönüşmesi', 'Selülozun her işlemde elmaslaşması'], 'Hamurlaştırma ve kurutma işlemlerinde selüloz lifleri kısalıp zayıfladığı için belirli döngüden sonra yeni kâğıt mukavemetini koruyamaz.'),
  ('Geri dönüştürülen kâğıttan baskı mürekkebini uzaklaştırmak için kâğıt hamuruna hava kabarcıkları ve yüzey aktif madde verilen aşama hangisidir?', 'Mürekkep giderme (flotasyonla deinking)', ['Kuru yakma (insinerasyon)', 'Asitle metal eritme', 'Süperkritik dondurma'], 'Flotasyonlu mürekkep giderme işleminde hidrofobik mürekkep parçacıkları hava kabarcıklarına tutunup yüzeye çıkar ve sıyrılarak selüloz liflerinden ayrılır.'),
  ('Elektronik atıklardan (e-atık) altın, bakır ve paladyum gibi değerli metallerin geri kazanılmasına verilen güncel sürdürülebilirlik terimi nedir?', 'Kentsel madencilik', ['Açık ocak tarımı', 'Biyolojik gübreleme', 'Atmosferik damıtma'], 'Kentsel madencilik, ömrünü tamamlamış elektronik cihaz ve kent atıklarındaki kıymetli ve nadir metallerin ikincil ham madde olarak geri kazanılmasıdır.'),
  ('Ürünlerin "al-yap-kullan-at" doğrusal modeli yerine kaynakların sürekli döngüde tutulduğu, atığın başka bir sürecin hammaddesi olduğu ekonomik model nedir?', 'Döngüsel ekonomi', ['Doğrusal tüketim modeli', 'Tek kullanımlık sanayi', 'Maden tükenme modeli'], 'Döngüsel ekonomi; tasarım aşamasından başlayarak yeniden kullanım, onarım, yeniden üretim ve geri dönüşümle hammadde döngüsünü kapalı tutar.'),
  ('Bir ürünün hammadde çıkarımından üretimine, kullanımına ve bertarafına kadar tüm çevre etkilerini ölçen sistematik değerlendirme yöntemine ne ad verilir?', 'Yaşam Döngüsü Değerlendirmesi', ['Kütle Spektrometrisi Analizi', 'Asit-Baz Titrasyonu', 'Kromatografik Ayırma'], 'Yaşam Döngüsü Değerlendirmesi (beşikten mezara / beşikten beşiğe analiz), bir ürünün tüm evrelerindeki enerji, su ve emisyon etkilerini nicel olarak hesaplar.'),
  ('Doğal gazın buhar metan reformasyonu ile hidrojen üretilirken açığa çıkan CO₂\'nin yakalanıp yer altında depolanmasıyla elde edilen hidrojen türü hangisidir?', 'Mavi hidrojen', ['Yeşil hidrojen', 'Sarı hidrojen', 'Kırmızı hidrojen'], 'Doğal gazdan elde edilen hidrojen CO₂ salınıyorsa gri, CO₂ karbon yakalama ve depolama (CCS) ile tutuluyorsa mavi hidrojen olarak adlandırılır.'),
  ('Bitkisel atık yağların veya hayvansal yağların (trigliseritler) bazik katalizör eşliğinde metanolle tepkimeye girerek biyodizel (FAME) oluşturduğu tepkime hangisidir?', 'Transesterifikasyon', ['Polimerizasyon', 'Nötralleşme', 'Süblimleşme'], 'Transesterifikasyonda trigliseritler metanolle tepkimeye girerek yakıt olarak kullanılan yağ asidi metil esterlerini (biyodizel) ve yan ürün gliserolü oluşturur.'),
  ('Biyoetanol yakıtının fosil benzine kıyasla teorik olarak "karbon nötr" kabul edilmesinin temel nedeni nedir?', 'Yanmada çıkan CO₂\'yi bitkilerin fotosentezle tutması', ['Etanol yandığında hiç karbondioksit üretmemesi', 'Etanolün içinde karbon atomu bulunmaması', 'Biyoetanolün yalnızca okyanus suyundan süzülmesi'], 'Biyokütleden üretilen etanol yakıldığında salınan CO₂, bitkinin büyümesi sırasında atmosferden soğurduğu CO₂ döngüsüne ait olduğu için net karbon artışını sınırlar.'),
  ('Termik santral ve çimento fabrikalarından çıkan CO₂\'nin bacada yakalanıp derin jeolojik formasyonlara basılması teknolojisinin genel adı nedir?', 'Karbon yakalama ve depolama', ['Fotokimyasal sis üretimi', 'Ozon tabakası inceltme', 'Termal inversiyon sistemi'], 'CCS (Carbon Capture and Storage), noktasal endüstriyel kaynaklı CO₂ salımını azaltmak için gazı amin yıkama gibi yöntemlerle tutup yer altında depolar.'),
  ('Kâğıt hamurunun beyazlatılmasında çevreye zararlı klor gazı (Cl₂) yerine yeşil kimya kapsamında tercih edilen ve yan ürünü su olan yükseltgeyici hangisidir?', 'Hidrojen peroksit (H₂O₂)', ['Kükürt dioksit (SO₂)', 'Karbon tetraklorür (CCl₄)', 'Hidrojen sülfür (H₂S)'], 'H₂O₂ ve ozon gibi klorsuz (TCF) ağartıcılar, dioksin ve klorlu organik bileşikler (AOX) oluşturmadan yalnızca su ve oksijen yan ürünü vererek beyazlatma yapar.'),
  ('Eski nesil çamaşır deterjanlarında suyu yumuşatmak için kullanılan sodyum tripolifosfat (STPP) yerine yeşil kimya yaklaşımıyla hangi mineral yapı taşı (builder) getirilmiştir?', 'Zeolitler', ['Kurşun oksit tozları', 'Cıva sülfür kristalleri', 'Kloroflorokarbon granülleri'], 'Gözenekli iyon değiştirici zeolitler Ca²⁺ iyonlarını tutarak suyu yumuşatır ve fosfatların yol açtığı ötrofikasyon sorununu ortadan kaldırır.'),
  ('Evsel ve endüstriyel atık sularda azot giderimi yapan biyolojik "nitrifikasyon - denitrifikasyon" sürecinin nihai zararsız gaz ürünü hangisidir?', 'Azot gazı (N₂)', ['Amonyak gazı (NH₃)', 'Azot dioksit (NO₂)', 'Hidrojen siyanür (HCN)'], 'Nitrifikasyonla amonyum önce nitrata (NO₃⁻) yükseltgenir; ardından oksijensiz ortamda denitrifikasyon bakterileri nitratı zararsız N₂ gazına indirgeyerek atmosfere verir.'),
  ('Doğada kolayca parçalanmayan, besin zincirinde yağ dokularında biriken ve Stockholm Sözleşmesi ile yasaklanan DDT ile PCB gibi bileşiklere ne ad verilir?', 'Kalıcı Organik Kirleticiler', ['Uçucu İnorganik Tuzlar', 'Hızlı Bozunan Biyopolimerler', 'Doğal Amino Asitler'], 'POP\'lar (Persistent Organic Pollutants) çevrede on yıllarca bozulmadan kalabilen, uzun mesafelere taşınabilen ve canlılarda biyobirikim yapan toksik bileşiklerdir.'),
  ('Yağmur suyunun toprak yüzeyinden sızarak çöp depolama alanlarından geçmesiyle ağır metaller ve organik kirleticilerce zenginleşmiş zehirli sıvıya ne ad verilir?', 'Sızıntı suyu', ['Saf damıtık su', 'Sert kaynak suyu', 'Glasiyel eriyik suyu'], 'Düzenli depolama sahalarında geçirimsiz kil ve jeomembran tabakalar kullanılarak sızıntı suyunun yeraltı sularına karışması engellenir ve ayrı arıtılır.'),
  ('Boya, vernik ve yapıştırıcı sektöründe yeşil kimya kapsamında geleneksel organik çözücülü boyalar yerine su bazlı boyalara geçilmesinin temel çevresel faydası nedir?', 'Uçucu organik bileşik (VOC) salımını azaltması', ['Boyaların kurumasını tamamen imkânsız kılması', 'İçindeki ağır metal kurşun oranını artırması', 'Sadece yüksek sıcaklıkta fırınlanabilmesi'], 'Su bazlı kaplamalar kururken atmosfere fotokimyasal sis öncülü ve toksik VOC buharları yerine büyük ölçüde su buharı salar.'),
  ('"PFAS" (per- ve polifloroalkil maddeler) grubu bileşiklerin yapışmaz tavalarda ve su geçirmez tekstillerde kullanıldıktan sonra "sonsuz kimyasallar" diye anılmasının nedeni nedir?', 'Çok güçlü C-F bağlarının çevrede bozunmaması', ['Güneş ışığında birkaç dakikada buharlaşmaları', 'Suda hemen şekere ve oksijene ayrışmaları', 'Yalnızca volkanik patlamalarda doğal oluşmaları'], 'Karbon-flor (C-F) bağı organik kimyadaki en kuvvetli tekli bağlardan biri olduğundan PFAS molekülleri çevrede neredeyse hiç parçalanmadan birikir.'),
  ('İnşaat sektöründe Portland çimentosu üretiminin küresel CO₂ emisyonlarında yaklaşık %7-8 paya sahip olmasının kimyasal tepkime kaynaklı başlıca nedeni nedir?', 'Kireç taşının (CaCO₃) kalsinasyonunda CO₂ açığa çıkması', ['Çimentoya kasıtlı olarak kuru buz karıştırılması', 'Kumun suyla birleşip karbon üretmesi', 'Çimentonun sertleşirken tüm havayı yakması'], 'Fırındaki yakıt yakımına ek olarak CaCO₃ → CaO + CO₂ kalsinasyon tepkimesi doğrudan çok büyük miktarda proses kaynaklı CO₂ üretir.'),
  ('Kimya laboratuvarlarında ve endüstride "mikroölçekli kimya" (microscale chemistry) uygulamasının yeşil kimya açısından doğrudan katkısı nedir?', 'Reaktif ve çözücü tüketimi ile atığı azaltması', ['Deney sonuçlarını tamamen ölçülemez yapması', 'Yalnızca mikroskop altında deney yapılması', 'Kimyasal tepkime yasalarını değiştirmesi'], 'Deneylerin gramlar yerine miligram ve mililitre ölçeğinde yapılması hammadde maliyetini, tehlikeli madde maruziyetini ve atık miktarını büyük ölçüde düşürür.'),
];
